INSERT INTO `medconnectapp_appointment` VALUES (1,1,'2026-04-15 10:16:56.000000','2026-04-15 10:16:56.000000','SCHEDULED','2026-04-16 08:00:00.000000','Khám sức khỏe','Mệt mỏi','Đợi khám','2026-04-16 08:00:00.000000',1,1,4),(2,1,'2026-04-15 10:16:56.000000','2026-04-15 10:16:56.000000','COMPLETED','2026-04-15 09:00:00.000000','Đau họng','Ho, rát họng','Đã kê đơn thuốc','2026-04-15 09:00:00.000000',2,3,5),(3,0,'2026-04-15 10:16:56.000000','2026-04-15 10:16:56.000000','CANCELED','2026-04-17 08:00:00.000000','Mờ mắt','Nhức mắt','Bệnh nhân bận đột xuất',NULL,3,1,6),(4,1,'2026-04-17 01:16:33.855010','2026-04-17 01:29:41.317752','COMPLETED','2026-04-17 08:00:00.000000',NULL,NULL,NULL,NULL,8,1,10),(5,1,'2026-04-17 01:59:24.830589','2026-04-17 01:59:24.830609','COMPLETED','2026-04-20 14:57:30.289479',NULL,NULL,NULL,'2026-04-18 08:00:00.000000',8,1,10),(6,1,'2026-04-18 07:11:24.244240','2026-04-18 07:11:24.244269','COMPLETED','2026-04-20 14:57:30.289479',NULL,NULL,NULL,'2026-04-18 08:15:00.000000',8,1,10),(8,1,'2026-04-18 10:23:12.194890','2026-04-18 10:23:12.194916','SCHEDULED','2026-04-20 14:57:30.289479',NULL,NULL,NULL,'2026-04-19 08:00:00.000000',8,1,10),(10,1,'2026-04-20 14:47:12.386953','2026-04-21 16:11:44.359283','PENDING','2026-04-21 08:00:00.000000',NULL,NULL,NULL,'2026-04-21 08:00:00.000000',10,1,11),(15,1,'2026-04-20 15:56:03.993609','2026-04-22 03:39:02.568111','COMPLETED','2026-04-21 08:15:00.000000',NULL,NULL,NULL,'2026-04-21 08:15:00.000000',10,1,11),(16,0,'2026-04-23 08:08:41.904170','2026-04-23 08:08:41.904195','CANCELED','2026-04-27 00:00:05.581716','Bên để làm mà đang vẫn. Nếu hơn của từ. Cách từng như từ cái với.','Hơn trong điều cũng đó số có. Không là nào hơn.','Cái giữa đến trong và theo.',NULL,195,6,300),(17,0,'2026-04-23 08:08:41.954109','2026-04-23 08:08:41.954133','CANCELED','2026-05-04 08:07:09.037403','Như có đi vẫn về và cũng. Tại hơn khi đó.\nCũng lớn nếu sẽ.\nNày đó thì nếu. Có giống rất như.','Cách sau không không số là cái. Mỗi bên để và với.','Như khi và. Tôi khiến hơn từ theo vậy.',NULL,187,5,331),(18,1,'2026-04-23 08:08:42.006184','2026-04-23 08:08:42.006211','SCHEDULED','2026-04-13 20:55:10.598982','Và tự không hơn. Đi chỉ thì.\nNhưng gần lớn về đã. Lớn trong như giống.\nGiống bên khiến. Về thế với.','Như cũng mà được từ như. Trong đã gần. Theo gần nào lớn.\nCác tại bên cách. Vậy các cho sẽ để.','Của không chỉ chưa được số.','2026-04-13 20:55:10.598982',329,6,297),(19,0,'2026-04-23 08:08:42.037968','2026-04-23 08:08:42.037988','CANCELED','2026-05-04 16:08:18.251877','Vài thế tự không bạn. Nơi thế cũng không và. Cách của để đến. Nào vài vậy với để để.','Với khiến là với bên. Thay đi với cũng đó người để. Nhưng của không làm tại để đi từ.','Hoặc như làm. Đi hoặc về được nơi từng mà.',NULL,171,7,235),(20,1,'2026-04-23 08:08:42.075281','2026-04-23 08:08:42.075302','SCHEDULED','2026-04-14 05:44:26.655563','Nào có với chưa.\nSố bên hoặc cũng đến tại làm.\nVài vài dưới như bạn giống thế. Lớn dưới có.','Cái vẫn lớn các bên số có. Cách cách rất của sẽ cũng làm. Với tại làm chỉ từ và.','Tại như và nếu. Với vậy khiến nơi vài hoặc.','2026-04-14 05:44:26.655563',269,7,300),(21,1,'2026-04-23 08:08:42.122155','2026-04-23 08:08:42.122172','COMPLETED','2026-05-21 11:18:31.666685','Tự khi tại có điều người từng đang. Giữa giữa tại để cũng và.','Vài thì này chỉ nhưng của một. Là sẽ nhưng hơn cũng như. Tại đang nhiều vài được nếu.','Số vẫn mỗi hơn thế. Vậy này để đến cách.','2026-05-21 11:18:31.666685',217,10,274),(22,1,'2026-04-23 08:08:42.149116','2026-04-23 08:08:42.149135','PENDING','2026-04-19 03:09:09.711609','Làm để làm để nhưng vì sau. Của có gần giống các. Nhiều mỗi giữa gần đó. Làm đi cách nếu này.','Nhưng cũng hơn. Vài như và cũng cho trong. Người nhiều là như vì vì giống.','Làm nếu tôi. Làm lớn cách cái. Vài chưa để sẽ.','2026-04-19 03:09:09.711609',340,9,274),(23,1,'2026-04-23 08:08:42.165109','2026-04-23 08:08:42.165128','SCHEDULED','2026-03-30 22:06:15.884681','Sau đến cũng và để trong như. Khiến chỉ chỉ tự cách nào trong người.','Để tại bên hơn cho để và. Đến mỗi nhiều hơn tại nhưng mà giống. Đó như cách này theo khi để để.','Chưa làm của từ giữa theo để. Tại mà làm.','2026-03-30 22:06:15.884681',298,7,160),(24,1,'2026-04-23 08:08:42.212858','2026-04-23 08:08:42.212878','COMPLETED','2026-05-09 14:16:43.923280','Cách bên với thay vẫn thế. Đó để đi. Vài chỉ cho đó đang.','Người một không khiến. Như cái thì.\nNhiều một người trong. Đúng rất cho từ hơn.','Vài từ đó từ số nào trong.','2026-05-09 14:16:43.923280',225,5,342),(25,1,'2026-04-23 08:08:42.251975','2026-04-23 08:08:42.252005','PENDING','2026-05-03 23:02:45.425569','Các đúng của đến về. Như trong về tại.','Thế thay mà chưa tôi bạn chưa. Lớn đi không hoặc đang tôi này đúng. Cũng được để của hơn đó.','Mà như các đến về. Khiến thì để hoặc có số gần.','2026-05-03 23:02:45.425569',182,5,222),(26,1,'2026-04-23 08:08:42.286534','2026-04-23 08:08:42.286552','PENDING','2026-04-11 06:35:16.446503','Cái đúng cách như để. Hơn đang không mỗi của sẽ. Điều làm bên gần có.','Khiến cái chỉ vài. Trong dưới của trong dưới.','Tôi bạn vẫn rất cách bạn. Như có sau tại hoặc.','2026-04-11 06:35:16.446503',218,7,160),(27,0,'2026-04-23 08:08:42.318160','2026-04-23 08:08:42.318180','CANCELED','2026-04-10 16:02:00.399716','Một khiến hoặc mỗi nhưng từ theo. Bạn vài đúng tự làm nơi sẽ làm. Cũng với sau điều tại.','Cho có để vài cho để. Để với đến cũng.','Của về là nơi nhiều từ.',NULL,340,6,199),(28,1,'2026-04-23 08:08:42.363280','2026-04-23 08:08:42.363312','COMPLETED','2026-05-13 10:06:52.513730','Với thay với số đến bên. Thay của được hoặc vài này. Điều cũng với để.','Tự gần không. Thì sẽ như. Có có nếu khiến tôi như không.\nMỗi các từ đó.','Các được vì. Như này nào của bạn.','2026-05-13 10:06:52.513730',154,9,274),(29,1,'2026-04-23 08:08:42.398483','2026-04-23 08:08:42.398506','SCHEDULED','2026-04-27 21:12:36.009678','Cách và theo là tại đã. Đó giống khi tại đi cách như.\nBạn để với mà. Từ là nơi và hơn và vẫn của.','Cũng đi làm từ người.','Tại như mà và như thay.','2026-04-27 21:12:36.009678',257,10,265),(30,1,'2026-04-23 08:08:42.440541','2026-04-23 08:08:42.440564','PENDING','2026-03-31 19:31:34.832444','Giống rất hơn tự để.\nGiống từ từ nếu nếu. Từng không đúng có.','Từng theo cho sẽ hoặc. Tự một chưa nhưng của với cũng cũng.','Vì dưới nào được để. Thay đó nơi tại như cách.','2026-03-31 19:31:34.832444',346,10,314),(31,1,'2026-04-23 08:08:42.492104','2026-04-23 08:08:42.492121','PENDING','2026-04-06 23:08:51.705028','Theo số như. Bạn đúng có khiến đi đúng. Một với không đúng vậy theo của.','Tại nhiều nếu để cho sau. Để nhưng số.','Hơn tại cũng với. Và điều đã để cho khi tôi.','2026-04-06 23:08:51.705028',176,8,244),(32,0,'2026-04-23 08:08:42.515663','2026-04-23 08:08:42.515678','CANCELED','2026-05-09 20:12:07.737650','Giữa một vì giữa cũng nếu rất về. Với theo tự trong như. Như chỉ để với người tại đã.','Như là thế theo. Khiến nhiều là lớn đi gần. Hơn như hơn.','Làm trong gần tại. Hoặc tôi được có cũng đã.',NULL,334,8,254),(33,0,'2026-04-23 08:08:42.559235','2026-04-23 08:08:42.559257','CANCELED','2026-04-17 07:06:18.933930','Sau thế tự. Nhiều sẽ người người được. Nhưng các điều là sẽ nếu. Từ đang cũng thế và đã khiến.','Với là và nhiều chỉ. Về về không này chưa với tại mà. Thay với để cách để như.\nBên cũng với trong.','Cũng có theo từng để là nơi hơn.',NULL,271,9,174),(34,1,'2026-04-23 08:08:42.606500','2026-04-23 08:08:42.606527','SCHEDULED','2026-04-25 01:20:40.682154','Vẫn nơi đúng đến điều giữa. Để dưới người nhiều như. Giống trong các trong vậy.','Chưa đến lớn hoặc. Rất điều khi của cũng khiến số. Tôi gần để.','Của của đi từ bạn vậy từ.','2026-04-25 01:20:40.682154',322,8,268),(35,0,'2026-04-23 08:08:42.652178','2026-04-23 08:08:42.652199','CANCELED','2026-05-06 02:56:52.334910','Để vì thế hoặc cho. Đi cho nào về từ tại.','Của giữa vì giống có. Với mỗi vài làm về tại hơn.','Số cho trong để với. Nào hơn đi.',NULL,210,10,267),(36,1,'2026-04-23 08:08:42.689371','2026-04-23 08:08:42.689394','PENDING','2026-05-02 03:21:48.160793','Dưới trong của gần vì. Tại tại như. Từ đã đã để khiến số để.','Tại tự vài cũng hơn theo. Theo có cũng nào bên nào.','Tự cũng của như và với. Dưới trong nào giống của.','2026-05-02 03:21:48.160793',299,5,297),(37,1,'2026-04-23 08:08:42.734438','2026-04-23 08:08:42.734458','PENDING','2026-05-13 09:15:15.210521','Chỉ được của giống. Để chỉ sau là.','Chỉ bên như nhưng để nào từ tự. Mỗi tự người số đi tại với.','Cách dưới thay tôi nào hoặc cho.','2026-05-13 09:15:15.210521',150,5,274),(38,1,'2026-04-23 08:08:42.759783','2026-04-23 08:08:42.759803','SCHEDULED','2026-04-18 00:11:58.314268','Với cho trong đó được. Về số với gần tại tự. Tại người đi đang rất để.','Nhưng để hơn. Tại cách thế để thì nhưng về. Mà dưới để hơn.\nCó thế chưa của. Làm của của đã thì.','Nhiều cách để nhưng từ. Đang thế như thế được từ.','2026-04-18 00:11:58.314268',179,5,254),(39,1,'2026-04-23 08:08:42.783234','2026-04-23 08:08:42.783251','SCHEDULED','2026-05-12 15:38:24.614747','Vài như thế số. Cũng đến để cũng tại từ vẫn. Lớn sẽ sau vẫn gần thế. Cái chưa số cái dưới với.','Thay sau nếu vì thì.\nTừ tôi đúng. Sẽ chỉ theo giữa một tôi trong. Vì lớn trong đó với.','Thế bạn với của cách và.','2026-05-12 15:38:24.614747',336,5,289),(40,0,'2026-04-23 08:08:42.828439','2026-04-23 08:08:42.828465','CANCELED','2026-05-20 05:33:23.019586','Bạn để nào. Có đã để sẽ từ của mỗi.\nKhông như cho nào. Của với tôi lớn. Từ đúng sau dưới nào.','Sau cho như từ được để một. Đó số theo bên từ đã. Một này tại như thì cho để.','Trong thế với thì. Với đến gần với nơi từ.',NULL,305,5,268),(41,0,'2026-04-23 08:08:42.869571','2026-04-23 08:08:42.869593','CANCELED','2026-05-13 08:55:33.215840','Nếu với chỉ bên được. Trong của được đến giữa hơn. Đã nhưng giống cái để của để đến.','Về từ từng người trong. Vậy khi rất bên có.','Bạn đã điều của thế khiến với thì.',NULL,339,7,301),(42,1,'2026-04-23 08:08:42.908896','2026-04-23 08:08:42.908920','SCHEDULED','2026-04-12 13:11:18.792870','Đang sẽ khi được thay. Của được tôi điều giữa vì.\nMột đúng đi làm bạn như. Từ cũng hoặc từ.','Lớn thay vậy hơn các. Của như dưới hơn.','Giống đó điều. Chỉ giữa để lớn mỗi nào.','2026-04-12 13:11:18.792870',165,7,235),(43,0,'2026-04-23 08:08:42.939943','2026-04-23 08:08:42.939963','CANCELED','2026-05-10 22:40:06.487089','Như giống cách. Sẽ đi nhiều trong hơn rất cái sẽ. Như cũng khiến về nào tôi hoặc.','Khi rất tại hoặc. Cho có nhưng để cho. Từng cũng của về khi sau vài lớn.','Với đó gần và lớn. Điều mà với được hơn.',NULL,315,10,160),(44,1,'2026-04-23 08:08:42.972712','2026-04-23 08:08:42.972737','PENDING','2026-04-30 17:49:03.912248','Cái đang giống vậy sau là.\nCủa số để sẽ như thay từng.','Đang nếu khiến. Theo được bạn đó đi về. Của và nhiều như nào như bạn.','Để tại hơn thế vì. Có của khi tại như.','2026-04-30 17:49:03.912248',200,9,152),(45,1,'2026-04-23 08:08:43.001577','2026-04-23 08:08:43.001601','PENDING','2026-04-11 21:24:52.857948','Sau gần của hoặc. Đúng hoặc từ như điều gần từ. Không nhưng hơn trong. Mà dưới hoặc người.','Số trong nơi làm. Tự hơn số không cách không mà.\nGiữa bạn cách nhưng. Hoặc vậy từ số dưới.','Điều gần khi không vậy từ.','2026-04-11 21:24:52.857948',264,10,152),(46,1,'2026-04-23 08:08:43.042735','2026-04-23 08:08:43.042758','COMPLETED','2026-05-19 11:06:44.511656','Một để cho mỗi. Với để bên tự sau nào được.\nCũng và vậy. Vậy mỗi đến người.','Bạn khi nào với tự nếu. Cũng giống làm vẫn số đó.','Từng rất có cách. Rất khi tại điều khiến.','2026-05-19 11:06:44.511656',192,5,237),(47,0,'2026-04-23 08:08:43.060995','2026-04-23 08:08:43.061012','CANCELED','2026-05-07 09:01:05.247983','Đi để đi của tại thay của. Mà với nhiều được vẫn được với. Được vậy và dưới vẫn các vì.','Được về nếu sẽ từ. Chưa rất nếu làm để đang từ. Mỗi thế trong với.','Các bạn sau cũng một như đến.',NULL,255,6,274),(48,1,'2026-04-23 08:08:43.113302','2026-04-23 08:08:43.113316','COMPLETED','2026-04-08 10:36:54.678620','Với nơi này.\nTừng cũng thì chỉ tôi là. Cách cũng tại hoặc các cũng nơi để. Thay chưa vì có thế.','Về với thế cho mỗi hơn vì rất. Người chưa thay đang. Giống và của cách như rất với.','Thế thế để của cái mỗi khi.','2026-04-08 10:36:54.678620',164,6,267),(49,0,'2026-04-23 08:08:43.151694','2026-04-23 08:08:43.151721','CANCELED','2026-04-04 09:05:30.974094','Điều trong tại về như là. Và vài của. Theo trong như trong để như.','Hơn chưa về từng. Bạn tôi như tại như để chỉ.\nĐang cũng có. Tại như nhiều. Có cho hoặc như vì vẫn.','Tôi của dưới để tại số bạn người. Mỗi thế đang.',NULL,150,8,278),(50,1,'2026-04-23 08:08:43.177252','2026-04-23 08:08:43.177274','COMPLETED','2026-04-16 09:15:14.781373','Trong của với của. Một nếu từ. Cách nhưng bạn như cũng nhưng.','Hơn từng các tại. Một như này trong.\nTại lớn đã đến của vì của. Hoặc có tự bạn.','Để nào trong như. Rất nếu đó tại.','2026-04-16 09:15:14.781373',212,9,160),(51,1,'2026-04-23 08:08:43.232199','2026-04-23 08:08:43.232220','PENDING','2026-04-04 08:12:05.405207','Khiến nhưng rất đến đúng. Đúng thế này hơn số.\nCó rất như hoặc của cũng. Cũng và không sẽ.','Vậy từ vài chỉ tự vẫn. Giống tự đúng hoặc.\nTừ số không chỉ cho đến. Như trong trong để như với.','Để của là đã số mà. Đã trong theo đi giống.','2026-04-04 08:12:05.405207',306,5,300),(52,1,'2026-04-23 08:08:43.257521','2026-04-23 08:08:43.257546','PENDING','2026-05-18 09:30:20.628958','Và như nhưng thế.\nVới đúng nào hoặc tại. Hơn nhưng số của để chỉ của. Cũng nào tại khiến giống sau.','Gần đúng thì theo tại bên của. Khiến để nơi bên tại vài trong.','Hoặc đến các giữa vậy bạn cách.','2026-05-18 09:30:20.628958',258,10,297),(53,1,'2026-04-23 08:08:43.298171','2026-04-23 08:08:43.298192','PENDING','2026-03-31 00:34:52.076388','Bên trong này cũng đã đúng và lớn. Rất với của chỉ.\nĐể và giống có. Sẽ một có này điều giống khi.','Cách mà điều làm lớn khi. Đã bạn và. Nhiều rất nếu từng một.','Tại sẽ về đến sau.','2026-03-31 00:34:52.076388',318,7,237),(54,0,'2026-04-23 08:08:43.378809','2026-04-23 08:08:43.378842','CANCELED','2026-05-11 08:09:46.056286','Giống chưa hoặc bên nhiều. Có như vài bên. Tại cũng gần cái.','Vẫn trong đi của nhiều và đã đang. Vài đi bên nào như thế số.','Để để làm hơn và người sau từng.',NULL,164,10,238),(55,0,'2026-04-23 08:08:43.425137','2026-04-23 08:08:43.425159','CANCELED','2026-04-04 12:11:07.608673','Mỗi hơn gần số cái của. Từng trong về vậy hoặc cái là.','Mỗi giữa về như không của. Cách có từ có.\nThì cái đúng sẽ. Vậy làm cũng giữa không.','Nơi cho của bên. Vẫn vẫn đi hơn làm.',NULL,312,9,237),(56,0,'2026-04-23 08:08:43.468729','2026-04-23 08:08:43.468756','CANCELED','2026-05-20 06:01:07.599670','Theo trong từng cho chưa các chưa. Điều tại mà hơn hơn khi.\nVì đến tại nhiều để.','Hoặc từ sẽ như chỉ vài để. Từng thì nhiều. Hoặc như mà tự từ trong cách.','Của sau về làm này. Như cái bạn đó với có.',NULL,186,5,265),(57,1,'2026-04-23 08:08:43.514323','2026-04-23 08:08:43.514352','SCHEDULED','2026-04-26 10:14:13.199085','Từng điều cách để của để. Của người khiến giữa nhưng như bạn.\nThế như để khi. Có của dưới mỗi.','Giữa tại tự thế tự. Mỗi số cũng để. Cho một đến về trong thế hoặc.','Chỉ và tự. Tại sẽ chưa để trong chỉ vì.','2026-04-26 10:14:13.199085',205,8,215),(58,1,'2026-04-23 08:08:43.555346','2026-04-23 08:08:43.555372','PENDING','2026-03-29 21:00:04.823593','Là theo là làm. Thay một đã không.','Vậy cái sẽ thế cũng từng với. Của đến đi khiến bên thì. Cũng của đến nơi khiến.','Khi đang với các.','2026-03-29 21:00:04.823593',307,5,300),(59,0,'2026-04-23 08:08:43.600776','2026-04-23 08:08:43.600793','CANCELED','2026-05-02 04:44:50.236716','Của gần mỗi vì này. Và thì nơi đó các như của. Thì đã hơn được sau.','Như như có vậy. Chỉ đến theo vài là. Trong hơn chỉ mà này theo để.','Sau tôi và vẫn từ.',NULL,240,7,152),(60,0,'2026-04-23 08:08:43.647288','2026-04-23 08:08:43.647311','CANCELED','2026-04-12 15:54:29.159824','Cách chưa đó của với chỉ khiến. Của bạn vẫn thay tôi tại như.','Nhiều vậy đúng thay từ đó từ. Hoặc theo giữa.','Hoặc vài từ giống đang từ dưới.',NULL,173,10,238),(61,1,'2026-04-23 08:08:43.661029','2026-04-23 08:08:43.661047','COMPLETED','2026-04-19 01:28:21.564460','Vẫn tại từ vài tại thay được vẫn. Giống tự để sau nào. Thì trong được của vẫn như.','Giống đi của được. Tại với để cũng bên. Để chỉ vài có.','Theo thì dưới hoặc thế để với tôi.','2026-04-19 01:28:21.564460',328,9,300),(62,1,'2026-04-23 08:08:43.705100','2026-04-23 08:08:43.705121','COMPLETED','2026-04-06 10:01:04.234076','Các bạn và cho. Từ sẽ đã hơn.','Về để tôi trong. Rất có từ.\nDưới tự đến của vài khi. Một dưới vẫn của của.','Đi như vài như như. Với hoặc đang thế.','2026-04-06 10:01:04.234076',282,9,244),(63,1,'2026-04-23 08:08:43.723409','2026-04-23 08:08:43.723429','SCHEDULED','2026-03-25 14:59:26.136306','Cái đang như đúng sẽ bạn đúng. Có bên đã vì vì tại. Với thế như khi để. Cũng thế đó từng giống.','Vậy một các được cái. Thay vài nào dưới cái trong.\nCủa với một như từ như nhưng mỗi.','Mỗi về về. Mỗi có cái các từng người là.','2026-03-25 14:59:26.136306',148,9,244),(64,1,'2026-04-23 08:08:43.748153','2026-04-23 08:08:43.748173','PENDING','2026-05-14 17:41:29.507313','Có vậy có. Cũng có vì cũng khi đúng giống là.\nNhưng gần một. Cách theo vài sau số tại.','Như sau về thì nhưng cái. Vài sẽ vẫn đang khi đang. Tại cái cũng để người với có.','Vì vì có khiến cho như nếu. Số có dưới.','2026-05-14 17:41:29.507313',190,5,267),(65,1,'2026-04-23 08:08:43.779658','2026-04-23 08:08:43.779673','PENDING','2026-04-28 01:50:34.799669','Với mỗi chưa như về và khiến. Hơn đã để chỉ.','Trong bên với người chỉ không. Hơn vậy từ số và để để. Mỗi mà là nào như là.\nHơn chưa tại về hoặc.','Rất nhưng chưa giống nào của. Chưa với nào đó.','2026-04-28 01:50:34.799669',277,8,226),(66,1,'2026-04-23 08:08:43.834693','2026-04-23 08:08:43.834720','COMPLETED','2026-04-09 23:45:29.330361','Đó từ của như. Đúng sẽ vẫn đi trong vài.','Nhưng để được các thay gần để từ. Gần tại nào đi.','Sau rất thay theo nếu. Đó để để sẽ với.','2026-04-09 23:45:29.330361',327,5,300),(67,1,'2026-04-23 08:08:43.888541','2026-04-23 08:08:43.888555','COMPLETED','2026-03-26 09:12:22.654321','Nơi theo chỉ chưa. Tại một đúng lớn.\nSố đến từ chưa sau các này. Cũng là nào.','Làm sau để với. Trong như khi sau các chỉ. Đến nào cũng của vài đến với cho.','Hoặc được tự thì hơn hơn trong.','2026-03-26 09:12:22.654321',258,10,199),(68,0,'2026-04-23 08:08:43.934798','2026-04-23 08:08:43.934816','CANCELED','2026-05-06 15:34:39.348281','Số người chỉ đến sẽ làm bên đi.\nHoặc các nơi nếu. Theo để để gần từ. Để như đi để từ như.','Đang trong từng nếu vì như tôi. Gần đó này sẽ vậy theo đã này. Này đang lớn số.','Vẫn bạn như với gần được khi.',NULL,261,7,238),(69,1,'2026-04-23 08:08:43.957977','2026-04-23 08:08:43.958002','SCHEDULED','2026-04-04 22:09:46.803592','Với này lớn sau nhưng. Tự tại đến người người số. Một điều sau một nhưng với.','Sau vì chỉ hoặc.\nMột được và cái cũng. Bên giống tôi tôi có với vẫn. Không của người như đó của.','Các thế cách điều cách người cách. Có cho để để.','2026-04-04 22:09:46.803592',263,10,284),(70,1,'2026-04-23 08:08:44.000456','2026-04-23 08:08:44.000475','COMPLETED','2026-05-14 17:52:46.499895','Hơn hoặc trong thay để. Của để trong trong.','Cũng đang vẫn về về. Làm đang khiến hơn cái chỉ. Và là cũng vì số dưới.','Đúng khi cho đang. Các người một chưa có vì.','2026-05-14 17:52:46.499895',172,9,300),(71,1,'2026-04-23 08:08:44.039930','2026-04-23 08:08:44.039948','COMPLETED','2026-04-04 19:08:21.565221','Như cái khi điều gần. Hoặc mà với trong chưa có. Bên làm của chỉ từng.','Sau như đi từ. Đã từ hơn trong từ cũng. Người rất nhiều cách từ hơn.','Đến là để dưới.','2026-04-04 19:08:21.565221',251,8,152),(72,1,'2026-04-23 08:08:44.092573','2026-04-23 08:08:44.092591','SCHEDULED','2026-05-13 23:04:07.485369','Đến thì từ từ. Theo đi như. Lớn từ số này hơn.','Tự bạn đang số hơn. Vài như đang thì sau.\nĐang của của để. Bên sau được lớn để khiến tại như.','Tại hoặc vẫn từ. Như cách của nhiều khiến và.','2026-05-13 23:04:07.485369',183,6,206),(73,1,'2026-04-23 08:08:44.148703','2026-04-23 08:08:44.148729','COMPLETED','2026-03-31 01:29:46.590377','Của thì cách trong của nơi từng. Mỗi để là đang bạn vẫn đến.\nĐang mà từng trong của sẽ nào.','Để mỗi cách một tự. Sẽ như sẽ từ hơn nhưng cũng. Giữa tại cho với.','Tự người đúng vẫn thế vì chưa. Có đang không bên.','2026-03-31 01:29:46.590377',307,7,278),(74,1,'2026-04-23 08:08:44.192876','2026-04-23 08:08:44.192897','PENDING','2026-05-05 16:39:34.202748','Theo cái từ mà vài. Điều số cái sẽ cách chỉ đã. Điều cho các có không giữa.','Nhiều nào như. Theo lớn đến từ hoặc đã sau.\nĐó đến điều có. Có đó thế như về hoặc.','Dưới như để sẽ. Vì vài bên người để vì.','2026-05-05 16:39:34.202748',169,6,284),(75,1,'2026-04-23 08:08:44.245835','2026-04-23 08:08:44.245854','SCHEDULED','2026-04-02 07:17:29.263489','Tại như để trong là khi cũng. Với cũng các vậy của để.','Hơn với được như. Như như thì làm điều. Lớn tại trong vì đến.','Mỗi như nào. Các số vài theo.','2026-04-02 07:17:29.263489',192,6,278),(76,0,'2026-04-23 08:08:44.293796','2026-04-23 08:08:44.293821','CANCELED','2026-04-20 11:32:54.647261','Bạn thì thế để. Giữa điều chưa làm.','Người trong dưới cái bên. Tại hoặc này sẽ có chưa.','Tôi vài cách được thay tôi và hơn.',NULL,198,9,278),(77,1,'2026-04-23 08:08:44.322051','2026-04-23 08:08:44.322070','PENDING','2026-04-17 07:38:19.265445','Mỗi tôi của hoặc. Chỉ đang tại như. Điều người điều của vì từng thì đi.','Vì tại tại vậy như rất đến. Vài như đúng giống từng số. Mà được là trong tại.','Theo lớn về vậy đi. Mỗi như và. Hơn các vài.','2026-04-17 07:38:19.265445',207,10,160),(78,0,'2026-04-23 08:08:44.363815','2026-04-23 08:08:44.363842','CANCELED','2026-05-15 01:55:04.570525','Cũng có tôi chưa tại với bạn giống. Để hoặc trong.\nNhư theo để từ tự.','Làm rất sau như sau bạn điều tôi. Theo bạn tự mỗi.','Khi nơi tại. Đi điều là như nào số đó.',NULL,180,10,206),(79,1,'2026-04-23 08:08:44.383308','2026-04-23 08:08:44.383327','COMPLETED','2026-04-04 13:46:37.801121','Đã và rấ