INSERT INTO `medconnectapp_doctor` VALUES (4,'10 năm kinh nghiệm nội khoa tại BV Chợ Rẫy',1),(5,'5 năm kinh nghiệm chuyên khoa Tai Mũi Họng',2),(6,'Bác sĩ chuyên khoa II Mắt',3),(10,'5 năm kinh nghiệm',2),(11,'10 năm kinh nghiệm',3),(152,'Vẫn làm chỉ. Đã rất đang tại với như.\nDưới như không. Với mà các sẽ. Dưới một nào tại.\nCũng bên không người cái thì đúng từ. Chỉ dưới thế để như. Về hơn như nơi cái.',16),(160,'Là tại đã là một hơn nếu. Nhưng lớn có hoặc thay nhưng.\nChưa như với. Dưới đã đang.\nCó vậy cũng mà khiến trong mà. Số từ bạn mỗi thay làm.',15),(174,'Từ cũng đã đang được. Vài như có làm.\nVẫn làm này tôi. Nào giống chỉ từ từng. Chưa làm hơn cũng có từng và mỗi.\nCó nơi từ đã thế nếu. Cái với để dưới. Nếu cái này từ nhưng.',17),(199,'Hơn chỉ giữa. Nhưng theo tại như.\nNào với được hơn. Theo từng sau đến cũng là mà.\nCủa khiến với giữa tại số. Với bên khiến nếu hơn. Nhưng như cách như nếu của giống. Về từng vài thay sẽ từ các.',13),(206,'Đúng số của nào. Số đến sẽ.\nMột sau như. Giống sẽ thế thế. Tại được và như bạn. Đang đã đúng lớn.\nHoặc với với điều. Của cách này với hoặc lớn như.',16),(209,'Cũng tự như nơi. Hơn cho và giống giữa lớn.\nNào bên về nhưng tôi.\nCó đến sẽ làm chỉ. Tự điều hơn đúng cách từng đúng.\nNhư như chưa trong các về. Khiến được khiến. Như vì hoặc cách vì cho như.',18),(215,'Hơn làm giữa. Một dưới như giống. Về đã cũng khiến đến theo.\nGần bên tại cái nơi. Một như thế đến để mà được.\nSau tôi như đó. Trong chưa tôi có cho.',17),(220,'Và chỉ của để hơn chỉ như vẫn.\nLàm được tự thay về với. Như chưa cách đang nào.\nHơn như khiến có. Cho có với các điều đã. Của giữa từng đúng gần đã.',12),(222,'Khi gần này hoặc này. Tại cũng mà đang vài thế đi. Các của từng.\nVì vài là. Vài rất là nhưng nếu của nhiều.\nNếu người nơi tôi của không giống. Một giữa không tôi cái dưới.\nMà một các của trong vẫn.',12),(226,'Khiến được hoặc đang.\nĐi cho cái với để cách hơn đúng. Này thì trong tại. Từ của nhiều trong. Như đang mà.\nNhư giống cũng thay của một thế. Một gần tại để như từ điều.',12),(235,'Cách theo của theo. Điều với thay của. Nhiều nào người được bên từ.\nTừ các không là. Nào như sau trong lớn. Của như chưa.\nKhi như chỉ như vẫn hơn có. Đi bạn hơn lớn nào hơn. Nào vì đi để của.',16),(237,'Như đến khiến. Có để đang.\nGần sau vài một nếu hơn. Khiến điều điều bạn đã. Lớn đi thế cho.\nMột nơi các như. Dưới vài thay cũng.',17),(238,'Giống như của cách nếu không tại các. Có đã nếu như. Của như chưa khi cách tại trong nào. Dưới từng để với như chưa.\nBên đó như với này. Mỗi không vì thì các được. Cái để nhưng như tại như dưới.',17),(244,'Đi số làm thay là và đi. Các của vậy thế như thay. Lớn mỗi về là.\nVài tôi sau rất tại từng giữa như. Có như không đến của vẫn tự của. Có vài chỉ cho của với.',16),(245,'Các để bạn lớn này cũng. Sau thì của như của như. Để nơi như nhưng đang từ cũng. Chưa rất vậy từ đang để.\nTừng cũng chưa như đi bạn này. Sau nơi thế cái của. Nhiều gần nhiều cách đã trong vì.',13),(254,'Như chỉ đang như trong. Như đang chưa thay giống trong là. Chỉ rất làm không sẽ gần.\nĐã từ các cũng. Tự tại theo tại sẽ gần. Được giữa cũng mỗi.\nNào trong thế có chưa nếu như để.\nNhư để gần một.',13),(265,'Lớn hơn cho khi có như chưa. Tự người cái cái sẽ. Và làm vì đó trong tại.\nNgười về thay hơn. Gần dưới cho điều từng cách.\nKhiến để tôi từ cũng thay. Đến nếu là như giống. Tại nào người vẫn tự trong.',16),(267,'Và hoặc như khi theo đúng khiến. Không đi được các tại sau được.\nKhi là như nhiều người. Trong của làm như.\nTừ như trong để. Nhiều hơn nhiều điều có từng lớn. Sau tự gần từng đã một.',12),(268,'Đã số như tôi sẽ.\nNhư bên nhưng tại vì.\nMột tự như đã để nào. Tôi bên của với như sau mỗi mà.\nCũng không đã là. Khiến nhưng vẫn nếu là lớn. Làm với từ cũng vài vài tự.',15),(274,'Vẫn gần đang. Số các vậy như. Người cách tự để đi trong.\nVài nhiều dưới rất để. Cái khi điều chỉ có đến. Rất cũng cũng đúng điều như vẫn.\nChưa cách cũng như. Làm của mỗi giống và.',12),(278,'Giống là vì mà có từ. Các về cho từ.\nVẫn từng đi trong cho.\nVề hơn lớn cách nếu mà sau vì. Khi nào sẽ cách các khiến tại. Vài chưa sẽ với lớn để. Trong của này được chỉ.\nMột nào về điều của bạn.',16),(284,'Nếu vậy giữa vậy. Nơi sẽ chưa mà cái với để.\nVới lớn bên như. Như với vậy làm cái. Vài số thay được.\nVới số bên vài đang sẽ sau như. Vài về bên. Các bạn số.',12),(289,'Nếu nhiều vậy. Cái nhiều các đi là vẫn có.\nNhư tôi giữa đó của làm để cho.\nVới nào như đang nhiều nào bên. Như hơn khi này nào đó trong gần. Của giống vậy đó như.',14),(297,'Rất cũng có. Cái bạn thay đó điều.\nTự sẽ rất đúng. Cái cách từ khiến nhiều rất làm từ. Một để lớn của như cái bên.\nKhiến lớn trong gần lớn.',12),(300,'Gần này đi hơn trong. Nhưng từ được nơi của. Dưới hơn tại vậy bạn khiến lớn có.\nCho đến hơn từ vẫn như. Đó là một theo trong cũng tại. Gần có nào giữa. Hơn giữa hơn nếu trong người dưới gần.',16),(301,'Nếu vài nhưng đi bạn đang để. Từ nhưng gần điều. Đó khiến và bạn chỉ chưa.\nTôi nhiều người. Giữa theo nếu thì. Sẽ và vì vài tự được đi như.',17),(314,'Cho giữa bên hoặc thay từ. Hơn nhiều để như rất đó trong.\nTại như bên từ. Cũng giữa từ của vài.\nLà có nhiều thế gần như nhưng được. Tại điều bên hoặc đúng dưới mà. Thì hoặc với đến nếu có từ.',18),(317,'Gần dưới lớn được. Của khiến đang đó hơn làm đến đến.\nCó vì nhưng đã đã thế tại nếu.\nNhiều chỉ và từ nơi. Trong từng như đó giữa cách điều. Như nhưng không vì cho với vài mỗi.',16),(331,'Nơi một nào số hơn với nhiều. Nếu hơn nhiều lớn như đi các đã.\nCác dưới nào.\nTừng như nhưng để dưới vậy. Khi từng cũng nào các.',18),(342,'Cách nhiều có cũng nhưng. Mỗi tại bạn để.\nVài có của cũng vài. Đang đúng về cũng làm.\nCũng như điều đến điều trong các. Không nhiều của nếu vì.\nĐi bên người dưới vì như. Đó giữa số lớn cái gần vậy.',17);
/*!40000 ALTER TABLE `medconnectapp_doctor` ENABLE KEYS */;
UNLOCK TABLES;

