INSERT INTO `medconnectapp_specialty` VALUES (1,1,'2026-04-15 10:16:56.000000','2026-04-17 03:33:24.677605','Nội tổng quát','Khám các bệnh lý nội khoa cơ bản','image/upload/v1776396806/fec8pammvssecbdpf08i.png'),(2,1,'2026-04-15 10:16:56.000000','2026-04-17 03:33:13.244613','Tai Mũi Họng','Chuyên khám và điều trị Tai Mũi Họng','image/upload/v1776396795/wdey9rel2mkaz5jlb9ms.png'),(3,1,'2026-04-15 10:16:56.000000','2026-04-17 03:26:54.052082','Mắt','Khám và đo khúc xạ mắt','image/upload/v1776396416/op8zrf2s56fuzc42xwxi.png'),(4,1,'2026-04-17 03:34:20.932604','2026-04-17 03:34:20.932664','Xương khớp','Điều trị các bệnh liên quan về xương khớp','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(5,1,'2026-04-19 03:23:46.958668','2026-04-19 03:23:46.958711','Thần kinh','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(6,1,'2026-04-19 03:24:01.387088','2026-04-19 03:24:01.387144','Hô hấp','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(7,1,'2026-04-19 03:24:16.902381','2026-04-19 03:24:16.902414','Ngoại tiêu hóa','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(8,1,'2026-04-19 03:24:31.193379','2026-04-19 03:24:31.193412','Nội tiết','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(9,1,'2026-04-19 03:25:22.580125','2026-04-19 03:25:22.580187','Phục hồi chức năng','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(10,1,'2026-04-19 03:25:30.718270','2026-04-19 03:25:30.718306','Sơ sinh','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(11,1,'2026-04-19 03:26:06.575228','2026-04-19 03:26:06.575283','Lão','','image/upload/Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(12,1,'2026-04-23 08:08:40.644316','2026-04-23 08:08:40.644333','Nội khoa','Vẫn nơi các vài. Chỉ người trong đó.\nNgười số vậy cho. Để và để của. Gần khiến có cái gần cho này.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(13,1,'2026-04-23 08:08:40.650944','2026-04-23 08:08:40.650961','Ngoại khoa','Khi với giống cho gần được hơn khiến. Với rất có gần giữa. Của vì là trong để về trong.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(14,1,'2026-04-23 08:08:40.656831','2026-04-23 08:08:40.656851','Nhi khoa','Chỉ của lớn vì không mà của cũng. Sau bạn tôi rất đúng khiến theo. Người người là thế cũng.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(15,1,'2026-04-23 08:08:40.663240','2026-04-23 08:08:40.663262','Sản phụ khoa','Mỗi cho giữa tôi chỉ đó bạn. Hơn nếu tại thì tại.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(16,1,'2026-04-23 08:08:40.668467','2026-04-23 08:08:40.668497','Tim mạch','Như người như tại đã theo cũng.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(17,1,'2026-04-23 08:08:40.674359','2026-04-23 08:08:40.674383','Da liễu','Được dưới số. Nào thì không vẫn nếu bạn của.\nĐể khiến từng. Chỉ một để như. Lớn hoặc này mỗi.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png'),(18,1,'2026-04-23 08:08:40.678943','2026-04-23 08:08:40.678966','Răng hàm mặt','Đó bên đúng đang. Tại đang không không.\nĐể rất giống của các. Mỗi với đã. Lớn nếu chỉ của.','Pngtree_doctor_check_the_eye_health_5315645_y7jg2j.png');
