INSERT INTO `medconnectapp_testresult` VALUES (1,1,'2026-04-21 05:39:36.861799','2026-04-21 05:39:36.861826','BLOOD','Hemoglobin: 13.8 g/dL','Bình thường',4,11),(2,1,'2026-04-23 08:08:41.922872','2026-04-23 08:08:41.922907','ULTRASOUND','Các bạn hơn nơi người rất hoặc. Thay của mỗi giữa cái vẫn. Tại hơn bên. Với để rất số.\nThế bạn cũng đó rất gần tự. Chưa về như. Từng bên cách tại tôi.\nCác nhưng nào như để. Sau trong với cái.','Thế vài nhưng đến cũng nếu mỗi như. Mỗi như điều một.',5,300),(3,1,'2026-04-23 08:08:41.978516','2026-04-23 08:08:41.978536','ULTRASOUND','Nếu tôi như giống cái và sẽ. Thay số khi thì của. Theo hơn điều có.\nHơn trong chưa vì số như. Cái đi chưa với.\nMột từ gần trong từ như. Về cũng giống vài. Cái hoặc thế làm.','Không trong có số được cũng là. Điều cũng người sau cho.',9,331),(4,1,'2026-04-23 08:08:42.052451','2026-04-23 08:08:42.052479','OTHER','Nơi dưới khiến vài với mà. Nếu hơn người bạn giữa sẽ. Thì giữa tự có từ.\nĐã này của. Cái vẫn đi điều về lớn tại này.\nKhiến như nơi thì từng đúng. Từ để vẫn như.','Thay tự về nơi nếu. Cách mỗi cũng cái tại.',11,235),(5,1,'2026-04-23 08:08:42.064204','2026-04-23 08:08:42.064224','XRAY','Đang như các và gần hơn làm thay. Chỉ này từ gần để.\nVậy tự đi.\nHoặc các hoặc mà là nhưng là người. Bạn và nào người từ vậy.','Trong điều có để hoặc đã lớn. Cách khi đó để một.',13,235),(6,1,'2026-04-23 08:08:42.091221','2026-04-23 08:08:42.091239','URINE','Trong khi khiến đã cũng. Là là sẽ như rất một.\nĐể chỉ thay đã điều. Như bạn giống vẫn được. Được mỗi là với cho lớn tại.\nTheo hơn chưa giữa như số đúng một. Của hơn được dưới vì.','Nào vậy vẫn hơn cũng. Từ thì như gần.',15,300),(7,1,'2026-04-23 08:08:42.111132','2026-04-23 08:08:42.111155','BLOOD','Cái nhưng giống được có giống. Đúng sau nào dưới. Nơi hơn vậy vậy cái hơn.\nCũng cũng này để của vì. Đến về dưới chỉ cách đã nhưng. Nếu của nào như người sẽ mà.','Sẽ của đi từng cũng khiến vì. Bạn mỗi mà là về với từ.',16,300),(8,1,'2026-04-23 08:08:42.136054','2026-04-23 08:08:42.136079','XRAY','Đến đúng nhưng từ từng. Một tôi gần khiến. Với tại tôi đã đó cho giữa.\nCho từ trong trong nếu vài nhưng đúng. Đúng trong từ vẫn để.\nNhưng đó của về vài điều. Đó tại người khiến.','Nếu rất nơi tại rất của tại thì. Của cho để. Bạn vài với cho hơn trong. Này thì làm như nào bạn.',17,274),(9,1,'2026-04-23 08:08:42.161506','2026-04-23 08:08:42.161527','OTHER','Từng nhưng theo chỉ gần. Như hoặc giữa được cũng đã.\nNhư đến để thế về vài. Chỉ với khi trong đó. Vì sẽ nào gần trong lớn đang.\nTừng gần từ vậy với đúng. Đang thì là đó từ của lớn.','Làm và cái. Sẽ là này đi lớn khiến người nhưng.',19,274),(10,1,'2026-04-23 08:08:42.179913','2026-04-23 08:08:42.179938','URINE','Sẽ thế người như khiến. Hoặc tại từng có nhưng.\nTừ người tại. Các từ bạn mà. Nhiều khiến đúng có gần tự bên.\nHơn cách điều thì. Mỗi dưới đã không để.','Cũng mỗi cái. Vài thế được giữa cũng tại trong.\nTheo đã như nhưng. Đến một với hoặc.',20,160),(11,1,'2026-04-23 08:08:42.186183','2026-04-23 08:08:42.186201','XRAY','Nào trong đang. Hoặc như giữa. Lớn từ gần sẽ người một.\nGiống và chưa của chỉ. Nếu một hơn. Khi bên rất không.','Đang và thay. Các đó của. Đến đúng từ hơn.',21,160),(12,1,'2026-04-23 08:08:42.193017','2026-04-23 08:08:42.193037','XRAY','Giống lớn hoặc một. Điều rất trong không nhiều để khi.\nCó trong cũng cái hơn như. Với về chỉ thì vậy với cũng. Hoặc sau tại từ rất.\nChỉ cũng cái như đúng vậy cái dưới. Số gần để về với thế.','Bạn mỗi giống mà giống được là. Với sẽ số tại cho nhưng rất.',22,160),(13,1,'2026-04-23 08:08:42.228158','2026-04-23 08:08:42.228182','BLOOD','Vậy làm của sẽ.\nNếu để một.\nNgười bạn từ đang với các. Cách được thế như có có. Từng để như cách.\nKhi hơn không thì cũng. Theo nhưng để mỗi hơn khi. Số các giống trong của không.','Chỉ để nào. Và hơn giữa được trong thì đi. Như được chỉ với đến thế.',23,342),(14,1,'2026-04-23 08:08:42.306438','2026-04-23 08:08:42.306461','BLOOD','Khiến cái khi. Đó đúng đó của đó. Cách có mà.\nĐến vì giống được bên tự các.\nSố như trong này. Nơi đó giữa nhiều cũng vài cách. Với để mỗi đó cũng.','Đang bên được như vì hơn. Vẫn cách thay số. Từ của về cũng giống.\nĐi như nhiều của đến.',27,160),(15,1,'2026-04-23 08:08:42.335611','2026-04-23 08:08:42.335636','BLOOD','Bên cái để giữa đã từ. Hoặc và trong. Như theo đang làm hơn cái tại có.\nĐã làm như đó giữa mà với.\nTrong hoặc thay giống đó vậy. Từ với để mỗi và khiến lớn.','Này chỉ để với.\nVài được đang bên cách nhưng. Của chỉ các các với.\nCũng tôi về nhưng. Các này của.',29,199),(16,1,'2026-04-23 08:08:42.416897','2026-04-23 08:08:42.416925','ULTRASOUND','Giữa để vậy thay vì này. Này làm hơn không đang với. Rất khi để với bên gần từ.\nCách số điều đó như nơi. Trong bạn đúng của. Từng mỗi cái đi như. Được như để.','Không trong đó của. Đã tôi làm vì. Đến không đi từ bên một có cái. Đúng mà theo tôi.',32,265),(17,1,'2026-04-23 08:08:42.455036','2026-04-23 08:08:42.455060','OTHER','Nhưng này cho. Cũng điều chỉ cho như như. Vậy theo để nếu mỗi vẫn từ không.\nCó đi của bên của của thế. Gần đi sẽ cũng cái bên về. Rất hơn nếu vài tại để không khiến.\nSố như và. Đó dưới về không để.','Rất với sau giống. Lớn theo cũng đi nếu.\nTừ cũng từng tôi vẫn mỗi đi.',34,314),(18,1,'2026-04-23 08:08:42.462751','2026-04-23 08:08:42.462770','ULTRASOUND','Thì như để trong bạn. Để tự trong các.\nNhư không rất và đang các gần. Đi bạn điều đúng vì nếu. Nhiều để có vài cũng người.','Một được như lớn đúng điều. Các trong thế với cũng. Tại cái khiến như.\nVẫn hơn như người như tại.',35,314),(19,1,'2026-04-23 08:08:42.505505','2026-04-23 08:08:42.505522','ULTRASOUND','Vẫn trong mỗi để.\nCác chưa của thay. Có giống giữa tự của để.\nMỗi tự đang đã cũng đi. Đến như đến thay đang đang từ cho. Không cũng nhưng của cũng đã.','Để từ sẽ không. Điều từ cũng như nhiều.\nMỗi nào đến theo. Cho mỗi lớn để được. Tại đến từ nào.',36,244),(20,1,'2026-04-23 08:08:42.512231','2026-04-23 08:08:42.512251','OTHER','Giữa khiến như và hơn đến đó. Để từ cho vẫn đến từng. Một để trong giữa vậy này mà.\nMột để hơn nếu cách để cách. Như vẫn đó mỗi trong của chỉ như. Tôi như thế có vì tại. Bên bên đến điều thế.','Thế trong về hơn đúng. Có từ từ vẫn nào.',37,244),(21,1,'2026-04-23 08:08:42.529811','2026-04-23 08:08:42.529833','URINE','Dưới cho này bạn tại. Mỗi sẽ thế.\nĐang như đang như như. Trong của khi tại không nơi cho.\nGần giống để. Vậy nào rất như nào.\nĐiều lớn vậy chỉ vậy vẫn mỗi tại. Không điều và bạn của trong theo.','Được đó từng có đang giữa. Không thay là cái có tôi của để. Đúng giống trong gần cách như.',38,254),(22,1,'2026-04-23 08:08:42.545259','2026-04-23 08:08:42.545280','XRAY','Vài các tự đó được cái. Của từ tôi mà.\nĐể đi gần điều đã nhiều. Vài nơi các là như tại sẽ của. Theo thì một của.\nMỗi của như tôi sẽ trong. Với trong tự thay mà của của. Mà như cũng.','Các là để cũng. Giống nếu bạn từng của.',40,254),(23,1,'2026-04-23 08:08:42.574335','2026-04-23 08:08:42.574359','XRAY','Đến một thế một có. Cách đúng nào giống.\nĐi dưới là cách tại đúng mỗi. Đó cái như số. Đã cũng dưới với cũng thế.\nĐã của như. Của tại đó bên thay đó.','Để hơn tự thế giống điều. Các đã giữa tôi là tại. Cái nào có như vì của.',41,174),(24,1,'2026-04-23 08:08:42.581422','2026-04-23 08:08:42.581443','URINE','Vẫn của của sau của nhiều.\nCó gần gần người với trong để để. Vì người của đang.\nHơn mỗi một số. Không từng như.\nHoặc chưa vài có từng. Một và được đi đúng thì nếu. Hơn cách cũng vì như giống nơi.','Có vẫn khi nào tại được. Cũng vậy sau từ vì tại.',42,174),(25,1,'2026-04-23 08:08:42.588153','2026-04-23 08:08:42.588173','ULTRASOUND','Đến cái để của. Tôi từ các gần rất hơn với. Như làm hơn về người. Được từng để để.\nLàm hơn mỗi vài rất đến để. Là nhiều như không tại sau của. Với số vậy tại từng nếu cho làm.','Nào tôi như trong đúng khiến bên có. Có gần lớn giống chưa chưa giống.',43,174),(26,1,'2026-04-23 08:08:42.621036','2026-04-23 08:08:42.621056','URINE','Đang giống với trong đúng trong. Dưới một điều.\nHơn sau về đi vậy. Hơn tại bên giữa tôi và.\nChỉ với thay là sẽ của điều số. Và đến tự hơn. Hơn bên cái mà như.','Đang này hoặc bạn bên đó. Từng nếu đến.',44,268),(27,1,'2026-04-23 08:08:42.628928','2026-04-23 08:08:42.628953','URINE','Được đang như như sau sẽ tôi. Là hơn để và tại.\nRất rất rất như. Nhiều đã hơn. Để người đã sẽ nhưng. Tại có được chưa thì vậy.','Hơn để với. Có của của nào khi cách. Đó về lớn tôi vì cũng tôi.',45,268),(28,1,'2026-04-23 08:08:42.668696','2026-04-23 08:08:42.668725','URINE','Rất theo hơn theo nhưng.\nLà của đã. Mỗi dưới là trong lớn.\nĐến bên có không tại cũng. Giữa cách cái.\nĐến nhưng vì bên nơi khi với nhưng. Số thế từ khi.\nĐang chưa thay điều với sau làm.','Giống tại thay theo nơi của. Vài mỗi sau trong tự. Khi rất chưa như.',47,267),(29,1,'2026-04-23 08:08:42.675297','2026-04-23 08:08:42.675317','BLOOD','Từ người trong từ là nhiều. Với khi cũng nhưng.\nĐể cũng bạn bạn gần vài với vậy.\nChỉ đó một đã một. Tại tại với các đã hơn.\nNgười một khiến bên. Hoặc dưới nào của và.','Số được với chỉ để hơn. Trong trong sẽ bên như. Các với chỉ đúng bạn cách.',48,267),(30,1,'2026-04-23 08:08:42.749458','2026-04-23 08:08:42.749480','ULTRASOUND','Như được tôi này tại giống từ cái.\nCách cũng thì đi cũng nhưng mỗi.\nHơn hơn hoặc sẽ sau mỗi vài. Đã dưới điều hoặc là. Không thì thì theo.','Để với cho đang khiến từng. Theo tôi nào cũng với tôi.',51,274),(31,1,'2026-04-23 08:08:42.776694','2026-04-23 08:08:42.776727','URINE','Đó và tại nhưng. Bạn tôi từ nào.\nSố vậy về dưới. Rất với người theo gần với nếu. Đó từ sẽ rất cái.\nNhư tại cũng chưa với như. Vậy điều tại đó.\nVà đã vẫn người hoặc. Tại thế rất với để thay.','Như giống là vậy từ. Đã đúng và để hoặc.',53,254),(32,1,'2026-04-23 08:08:42.847486','2026-04-23 08:08:42.847516','XRAY','Về vì mỗi. Đúng một cho không. Bên chỉ theo thay mỗi.\nKhi sẽ đã theo các. Gần đúng giống như khiến nhiều. Tôi cái các. Làm tại với tại từng.\nCác bên nếu cũng chưa vì. Này giữa chưa tự.','Rất hoặc cách khi chỉ để vẫn. Và để nhưng giống. Trong nào đang tại theo cách.',57,268),(33,1,'2026-04-23 08:08:42.885208','2026-04-23 08:08:42.885230','URINE','Của vài giống có mà. Hoặc được chưa.\nNgười như thay có đã làm. Có số làm mỗi đó có. Vì theo nhiều hoặc nơi.\nCái vì cách vì nơi. Với sau nào có để đi.\nNhưng cái về một khi chưa. Đang tại nếu để.','Đi trong đúng có các. Nhưng nhiều như trong đến thế. Nơi vậy trong thế như.',58,301),(34,1,'2026-04-23 08:08:42.896645','2026-04-23 08:08:42.896670','URINE','Người khi làm chỉ theo. Cái trong thay. Và nơi các cũng cho.\nTôi đi cũng thay đã bên trong.\nKhiến có thì nơi.\nSẽ khiến nhiều về hơn bạn như. Đang cũng một lớn.','Như thế vì giống. Bạn vẫn tự được như dưới.\nVới bên hơn vì để hơn. Đến chỉ dưới vẫn.',60,301),(35,1,'2026-04-23 08:08:42.926894','2026-04-23 08:08:42.926921','BLOOD','Đó cái đó là tôi mỗi như để. Không lớn bên của để làm. Từ không để thay rất.\nSẽ điều bên vì đúng mà dưới.\nSau cho vài bạn. Từ chỉ dưới của. Mỗi vẫn hơn như cũng với với.','Lớn để của hơn. Từ đến như các về của mỗi.\nBạn của cách vậy. Như số hơn thế.',62,235),(36,1,'2026-04-23 08:08:42.958017','2026-04-23 08:08:42.958045','URINE','Vẫn được đang trong này. Để có làm sẽ bạn đến được. Không để theo gần cái thế được có. Cho chỉ để lớn từng tự.\nVề để mỗi có. Vài có để như. Nếu chưa chỉ số số mà có.','Của rất sau với hơn của. Bên vài và đến và để.',64,160),(37,1,'2026-04-23 08:08:42.991791','2026-04-23 08:08:42.991817','XRAY','Thay dưới cái trong khiến vậy. Và các tôi từ. Đó cho rất đã về thì.\nVài mỗi và theo. Điều mỗi đang tại người các đến.\nVề với đó hoặc có từ từ. Lớn đang trong cách gần.','Nhưng này cũng đó về chỉ đúng. Trong rất với nơi. Giữa từ một theo.',67,152),(38,1,'2026-04-23 08:08:43.075034','2026-04-23 08:08:43.075061','XRAY','Tại với các người. Tự lớn đã trong và bên hơn khi. Cái từ có trong cũng từng cái. Cũng một nhiều mà thì một sau.\nTừ đã bên bên giữa về. Giữa gần gần cái hoặc hơn cũng.','Gần các được rất với như như. Của rất của từng của. Khiến để như.',72,274),(39,1,'2026-04-23 08:08:43.127077','2026-04-23 08:08:43.127094','BLOOD','Làm từ này và cho cũng hoặc. Để đúng cũng dưới như giữa vậy.\nVới và từ hơn. Vậy trong nơi.\nVậy có trong và. Nếu tại từ khi giống nào mỗi.','Cách đã của rất bên. Có lớn cái đi.\nCó tôi lớn nếu người điều bên chưa.\nTừ được hơn theo.',73,267),(40,1,'2026-04-23 08:08:43.166120','2026-04-23 08:08:43.166145','ULTRASOUND','Đang chưa có. Từ đã về. Các từ vì cách vài từ theo.\nĐể đó là cũng sau. Hoặc nào theo để. Chỉ nhiều với với chỉ vài người.\nNhư để điều hơn. Như vì với thì vài gần bên. Đúng khi theo thì.','Đến khiến chưa như cái cái. Để theo làm đã. Như đang của nếu trong của lớn hơn.',75,278),(41,1,'2026-04-23 08:08:43.197143','2026-04-23 08:08:43.197171','OTHER','Thì như cái các đã. Như nếu như nhiều.\nCũng nào rất cách này hoặc. Cách cũng như. Là đi thế như tại đã.\nTừ của như với thì như.\nNơi đúng nhưng hơn cũng của. Đến vậy hơn thay điều.','Của vài được khiến sau. Số sau giữa sẽ. Chưa đang đến trong với.',77,160),(42,1,'2026-04-23 08:08:43.208627','2026-04-23 08:08:43.208651','OTHER','Của bạn đúng điều. Vì vài bạn là thì về hơn.\nNhưng thay như không từ trong. Có khiến của cũng.\nNhư gần các của cách chỉ. Rất khiến hơn nếu dưới mà.','Mà khiến vậy thay của để. Người có hơn như được cũng nhưng. Lớn thế vài với thay.',78,160),(43,1,'2026-04-23 08:08:43.245766','2026-04-23 08:08:43.245780','XRAY','Trong giữa chưa cũng điều được. Với người tôi nếu cách cho. Mỗi từ như cũng chưa.\nCho tại như thay từng lớn hoặc.\nĐó lớn cách làm đi.\nKhông lớn từ. Theo đúng với đúng nhiều rất bạn từ.','Dưới nào từng từ nhiều. Lớn thì đang đã. Giữa sẽ chỉ như vậy.\nGần cũng từ một bên của.',79,300),(44,1,'2026-04-23 08:08:43.253416','2026-04-23 08:08:43.253425','URINE','Của như của giữa đang của hơn như. Chỉ hơn để.\nMà như vẫn rất để hơn. Theo và khiến hơn khi giữa tôi.\nMột đó thì. Có đi giống. Như của cách từng khi đến hơn.','Tự trong của. Chỉ được và của bên đó.',80,300),(45,1,'2026-04-23 08:08:43.273357','2026-04-23 08:08:43.273382','URINE','Như là cho để như với cái các. Đã làm vậy để. Rất như như như sau khi được có.\nCủa đang cái hơn. Như từ mà điều được nếu thì.\nNếu từ trong sẽ từng bên của. Để và của nào cách bên.','Có vẫn tại. Và giữa về nhưng. Của vậy với như.',81,297),(46,1,'2026-04-23 08:08:43.329415','2026-04-23 08:08:43.329437','BLOOD','Từng sau từng đó.\nGần bạn như cũng để dưới. Từ và sẽ một đã rất giống. Chưa đi điều như hoặc nơi từ. Số một điều lớn với cho.','Thì mà giữa. Vì có này này theo. Với và là hơn cũng này.',82,237),(47,1,'2026-04-23 08:08:43.343024','2026-04-23 08:08:43.343046','ULTRASOUND','Giữa về nơi cho. Được và từ để là về. Không như hoặc đến để vài chỉ.\nNhư trong có tôi. Mà các thay đúng nào. Chỉ bên và và.\nMà khiến sau hoặc như là của tại. Như của đang làm.','Nào nhiều dưới nhưng trong đó từng. Gần sau giữa đi gần là vài. Nếu với thay để để như bên.',84,237),(48,1,'2026-04-23 08:08:43.392913','2026-04-23 08:08:43.392936','ULTRASOUND','Không tôi mà sau. Thế khi của vài hơn trong. Mỗi người hoặc rất.\nBạn cũng hơn hơn bạn. Hoặc mỗi thế thì như giống cũng. Cho với như giữa.\nCái giống đến số mỗi nếu. Sau thì bên rất.','Vậy này từng và sẽ. Bạn tôi giống của từng. Vài nào như bên trong bên.',85,238),(49,1,'2026-04-23 08:08:43.403006','2026-04-23 08:08:43.403028','XRAY','Trong hơn thay khi các. Lớn giữa tại nơi từ nào cái.\nNhư về của. Mỗi về để cũng của. Không như tôi không gần như. Như của chỉ như khi.\nĐiều thay như về chỉ đã giữa lớn.','Hơn theo tự trong này mỗi vẫn. Điều chỉ nào thay đúng.',87,238),(50,1,'2026-04-23 08:08:43.449418','2026-04-23 08:08:43.449437','OTHER','Này từng trong đang. Mà rất tại trong nơi.\nCó không vài số đến sau. Làm đang nơi bạn cũng để giữa.\nSau cái khiến các để. Giống đến có để cách không mà thay. Một hơn nhưng vì về khiến.','Của tôi cách số với vài trong. Điều tôi số trong. Của vẫn đó đến cách.',90,237),(51,1,'2026-04-23 08:08:43.618209','2026-04-23 08:08:43.618229','URINE','Rất hoặc cho làm để khiến. Giữa một thì bạn nơi mỗi. Như nếu vì tôi.\nTrong của như có như được tại. Nơi nhưng cách. Vài rất của làm tôi được. Rất dưới nhưng lớn từ.','Chỉ có đang nếu một của nào. Người không theo chưa.',96,152),(52,1,'2026-04-23 08:08:43.719609','2026-04-23 08:08:43.719632','ULTRASOUND','Như mỗi chỉ và nếu như thì. Và theo của giống cũng từ.\nĐang đến tại về một này các hoặc. Sau tại có giống. Vậy thay cái đến cũng hoặc sau sau.','Đến đúng hơn khi từ để. Về từng có mà dưới tại.',99,244),(53,1,'2026-04-23 08:08:43.762384','2026-04-23 08:08:43.762413','URINE','Không một các thế được của từ rất.\nThế này khi hơn tôi.\nRất nhiều giống thay như như giữa. Lớn sau một chỉ trong. Thay để từ được.\nNhư làm với nào cũng đó khiến. Trong hơn vài hơn.','Cách làm từ nhiều.',101,267),(54,1,'2026-04-23 08:08:43.852173','2026-04-23 08:08:43.852196','BLOOD','Không đúng vì thì đang.\nTrong để cái tại từ giữa với. Của như sẽ đang tự tại. Từ nhưng thế đó hoặc.\nHoặc mỗi khi theo chưa với hoặc. Có vài hơn người.','Đến giữa theo cũng để được. Cái giữa đã.\nLà của số nào nhưng. Số có đến. Về làm trong cái.',105,300),(55,1,'2026-04-23 08:08:43.951907','2026-04-23 08:08:43.951933','BLOOD','Tôi hơn thì của làm đang nhiều.\nNhư nhiều là vài giữa thay nhiều. Để thì sau tại với vẫn cũng.\nĐã đi chỉ thì. Điều của đến nhiều một về giữa. Thế đó có trong hơn có.','Cho theo hơn có gần. Chỉ để các đúng với của thay. Gần nhiều trong để thì có khi.',108,238),(56,1,'2026-04-23 08:08:43.976511','2026-04-23 08:08:43.976536','OTHER','Nào gần bên có. Làm và vài thế. Vẫn từ thế và mà theo.\nCho để và của hoặc để. Các điều giống lớn của đến. Như dưới tại điều dưới chưa vẫn các.','Điều lớn tôi số như cũng. Bạn của làm hơn chỉ đã đã.',110,284),(57,1,'2026-04-23 08:08:43.982972','2026-04-23 08:08:43.982992','BLOOD','Về để cũng tại. Nếu về tự. Theo các của tôi tại như người.\nHoặc thì nhiều đúng. Cũng làm khiến như như.\nThay cho vẫn với hơn. Không không vẫn bạn tôi. Đó bạn với từ.','Rất và tại đang. Của đó để cho như đã. Điều theo đi đó rất với rất.',111,284),(58,1,'2026-04-23 08:08:44.014129','2026-04-23 08:08:44.014147','ULTRASOUND','Đó thay điều đi. Đang điều đang tự để. Để đó từ sẽ sau.\nNơi từ hơn của mà. Để nào hoặc giống từ được đúng. Đó các từ đó. Bên đó này để của tôi.','Sẽ mà từng người. Người để nhưng trong bên tại.',112,300),(59,1,'2026-04-23 08:08:44.025108','2026-04-23 08:08:44.025127','URINE','Như sau này từ một nhiều. Sau đang thay sau được.\nTừ của gần.\nTrong vậy mà đã thay người. Khiến tại cũng vậy. Tại nhưng hơn tôi với các dưới. Nhiều trong nơi gần giống có về.','Tại của của. Cũng của gần trong người.\nTrong vài bạn hoặc. Để giữa nhiều của.',113,300),(60,1,'2026-04-23 08:08:44.034001','2026-04-23 08:08:44.034027','URINE','Trong đang thế của. Vì của làm điều của như.\nVà hơn thay chưa. Từ cái và khi hơn như để.\nVì theo có thế người dưới từng. Vậy cho mà lớn như. Tôi của như sẽ. Với để sẽ cũng thay từ theo.','Của như sau. Hơn làm đúng với. Tôi giữa cái này bạn số.',114,300),(61,1,'2026-04-23 08:08:44.055261','2026-04-23 08:08:44.055289','BLOOD','Của được là nhiều. Từng tôi để mỗi mỗi như rất các. Có tại vì vậy.\nCủa có mà. Nếu chỉ để đúng.\nNhư với của làm vậy. Nhưng nơi với người khiến. Tự các giống cũng nhưng số.','Và có hoặc. Của để để gần thế. Của cho làm thì trong như.',115,152),(62,1,'2026-04-23 08:08:44.107308','2026-04-23 08:08:44.107331','XRAY','Với thay là rất tôi khiến không về. Sau nhưng cũng không. Mỗi làm không.\nGần giữa đó cái các bên vì. Có cũng theo trong từ. Của nào từ khiến thì gần.','Dưới có sau này cho vì từng như. Từ vẫn trong của. Thì chỉ vậy đang.',116,206),(63,1,'2026-04-23 08:08:44.116218','2026-04-23 08:08:44.116239','URINE','Khi vậy khiến bên về thay vài thế. Nếu đó làm nào đó trong nếu một. Mỗi dưới cũng thay điều cách cái. Thế để từng sẽ cũng nhiều cũng cũng.\nCác theo giống.','Để số hoặc sẽ đã trong đi sau. Nhưng dưới của điều. Sau thay tôi của thì từ vậy gần.',117,206),(64,1,'2026-04-23 08:08:44.122775','2026-04-23 08:08:44.122798','URINE','Nơi hoặc trong đang tôi. Với như vài nếu cũng. Hơn dưới nhưng chưa của khi.\nNhiều cái số. Hoặc để hoặc người. Tại này như về.\nCái dưới của như. Theo từ cái.','Cũng từ cũng nếu rất chỉ bạn hơn.\nCó tôi dưới để thay không. Tại như từ này để. Hoặc từ đi nơi.',118,206),(65,1,'2026-04-23 08:08:44.165522','2026-04-23 08:08:44.165541','OTHER','Theo thay để. Các đúng này cho. Theo vì vài tại như có đã.\nGiống nơi tại. Có để hoặc nhưng thế và khiến bên.\nCũng nhiều số cho số các mỗi. Khi đó cho cách thay. Cái đi có nếu.','Để đến cái cái tại của theo đi. Cũng tôi theo được. Thế gần của từ theo về. Giữa sẽ với thì.',120,278),(66,1,'2026-04-23 08:08:44.260041','2026-04-23 08:08:44.260063','OTHER','Hơn này cho lớn về trong với. Nơi chỉ với vì từ có.\nĐiều nếu rất làm gần để. Đi dưới từ nơi. Của sẽ giống một.\nSẽ tại đúng chưa. Được như trong cũng. Một để như đến hơn cách hơn.','Tự không giống.\nVới về như vài. Về gần cũng để để và khiến. Từng gần chỉ điều hơn.',123,278),(67,1,'2026-04-23 08:08:44.309138','2026-04-23 08:08:44.309168','XRAY','Tự hơn tại nào gần cho trong. Đó về nào đang các. Nhiều tự về được vẫn.\nNhư cũng cách cách tôi. Cho về vẫn vậy điều nhưng.\nNày để tại trong để. Đến sẽ thì vẫn làm theo. Để từ đi là.','Rất đang và để. Từng này cho thì.',125,278),(68,1,'2026-04-23 08:08:44.317913','2026-04-23 08:08:44.317935','BLOOD','Chưa người hơn cho. Đến số đã người đến đã điều.\nNgười đang người dưới thì giữa tôi. Vậy cũng nơi trong và từ từ bên.\nCủa không các từ vì hơn đúng. Trong đang có.','Vài có đang chỉ từ. Vài với làm vì để số.\nSau đi như cũng để và từ. Chưa trong bên theo khiến là.',126,278),(69,1,'2026-04-23 08:08:44.376289','2026-04-23 08:08:44.376309','OTHER','Là đến nhưng có. Mỗi từ tại là theo đã nhiều. Về vài như đúng sau.\nCủa để để từng và. Như sau dưới. Số có tự lớn rất sẽ.\nĐể đó bên số.\nKhiến đi cái của cái từ gần.','Thì hơn vì từng để vậy. Trong dưới người để.\nTheo chỉ nào để. Như vài đúng vài mà.',128,206),(70,1,'2026-04-23 08:08:44.398206','2026-04-23 08:08:44.398226','ULTRASOUND','Để của một. Giữa để thay cái của số số từng. Thế điều đi vì.\nKhiến vì thế bạn nơi vì tôi. Vì tại một bạn được thay thì hoặc.\nNơi để của đi. Mà số như đúng rất để. Của một như tôi tôi là đến.','Chưa về sau đã. Của bạn điều này vậy vì khi. Vẫn vài từng làm. Đã đó và mà giống các.',130,268),(71,1,'2026-04-23 08:08:44.422878','2026-04-23 08:08:44.422905','URINE','Đó nào cũng có một như gần. Bạn từ thay bên đi. Của nhiều mà nhưng từng nơi.\nVì vậy cho giữa như người. Hơn từ mà số. Nhiều về là các hơn đang dưới.','Chưa hơn hoặc và. Cho từ như tự. Đi đang làm vì tại để bạn.',131,215),(72,1,'2026-04-23 08:08:44.429750','2026-04-23 08:08:44.429780','URINE','Để sau về cho số giữa. Tôi hoặc như như. Đi vài chưa tự.\nThay rất đi với thì tại một. Như làm của mỗi. Nào như đã giữa hoặc người mà đó.','Từ rất mỗi vì tại về. Mỗi giữa chỉ nếu để tự hoặc.\nTừ nào đúng vì sẽ. Của vậy và của.',132,215),(73,1,'2026-04-23 08:08:44.473350','2026-04-23 08:08:44.473386','XRAY','Cho đang đi thì mà. Tại nếu tại thế.\nĐã mỗi khi chưa. Chỉ giữa vì đã tại. Người thì từ từ lớn điều như.\nCó cách vài nơi nào hơn không. Cũng cũng mà như sẽ chưa này. Nhưng như thay đó được số điều.','Rất từng với một lớn thế giống. Làm bên hoặc cũng đúng.',133,314),(74,1,'2026-04-23 08:08:44.519851','2026-04-23 08:08:44.519863','ULTRASOUND','Chỉ theo giống vài mà. Vậy đúng bên tự hoặc.\nĐể mỗi một cho khiến. Giữa đến có bạn và cách.\nCũng tôi giống của như sẽ. Như dưới cho nếu trong.\nNếu khiến có mà vẫn thì đó sẽ.','Như trong đã gần bên. Cho khiến rất gần.',135,220),(75,1,'2026-04-23 08:08:44.569157','2026-04-23 08:08:44.569179','OTHER','Đang khiến cách được. Về hoặc như nếu.\nTrong tự đang khiến cho làm cho như. Điều để khi như như được nhiều. Với hơn là như giống với tự.\nNgười vậy đã như này làm. Vài đã như như.','Sau như sau đang đúng như. Một các đã sẽ làm tại gần.',138,274),(76,1,'2026-04-23 08:08:44.658884','2026-04-23 08:08:44.658918','BLOOD','Về này mà tại. Nào nếu cũng. Như tôi không cho để.\nSố của để này điều sau rất. Tại không mà cái từ. Làm đúng như đi nào cách rất tại.','Như sẽ đúng nào cái để mỗi. Hoặc nhiều tự chỉ trong khiến dưới.',141,206),(77,1,'2026-04-23 08:08:44.672577','2026-04-23 08:08:44.672634','ULTRASOUND','Một được từ theo về. Và giữa nào đi hơn.\nLàm tại số trong. Này điều để nào nhiều này nhiều cũng.\nMà với có cho. Có tại của cũng như.','Từ điều chưa cái.\nMỗi trong như đó cũng bạn. Tại tôi đó là như. Điều nếu vẫn nơi và từ gần.',143,206),(78,1,'2026-04-23 08:08:44.888983','2026-04-23 08:08:44.889017','BLOOD','Nơi rất số như. Đúng của không nào một nhiều.\nGần thế khi bên. Để giữa cho của người các.\nVề giống này với. Đi và giống của.\nGiống được cũng theo với hơn.','Của cái nào sẽ vài mà để. Đi vài về rất đi về.\nTrong sau số như như như. Mỗi về tại như cũng đi.',150,209),(79,1,'2026-04-23 08:08:44.941732','2026-04-23 08:08:44.941760','XRAY','Vẫn với dưới nhưng cho hoặc như hơn. Đến bạn đi để. Tại thì thay các. Đến của đã điều về trong vài khiến.\nTheo nào cách giống của là. Khiến từ dưới bên này tự.','Tôi có với rất cũng. Một lớn cũng để để bên nhưng. Của từ từ thế dưới tại các.',151,152),(80,1,'2026-04-23 08:08:44.995258','2026-04-23 08:08:44.995288','OTHER','Từ với dưới bạn thế sau. Không về vẫn khiến để sẽ hơn. Của cũng dưới gần thế sẽ.\nVà rất đang của cũng lớn. Để đã vẫn như để dưới.\nĐến như với làm của của.','Đúng nếu mà đang hơn. Mà giống nhiều.\nSau cách tôi hơn tại có. Giống cái như trong.',152,238),(81,1,'2026-04-23 08:08:45.003600','2026-04-23 08:08:45.003627','URINE','Người của cách đi theo nhiều thì vậy. Đó được thì làm hơn của nhiều. Người như vài. Từng từng sau được này nếu.\nĐến đã cái đi theo. Số là không chưa chỉ khi như. Vẫn thay đến thì tại dưới nơi.','Không dưới dưới từ như từ. Như trong như gần nơi vài. Thì nào dưới nếu của nào.',153,238),(82,1,'2026-04-23 08:08:45.011877','2026-04-23 08:08:45.011906','ULTRASOUND','Tại chỉ đã nếu. Theo rất cách không.\nĐến để của. Rất theo gần đã như cách tự tự.\nĐi cho về người cái và như cho. Này khiến của để người hơn khi cách.\nMột và như từ người được như. Cho cũng tại tự.','Cách làm nào tôi đã vài. Để có và như tại.\nĐể nhưng vài người nếu. Nếu một từng để.',154,238),(83,1,'2026-04-23 08:08:45.112317','2026-04-23 08:08:45.112352','URINE','Đó để của hoặc không về. Một như sẽ hơn dưới đã.\nGần thì vẫn cũng hơn. Khiến đúng như tại giống các sau.\nNhư bên rất. Thì như hoặc.\nĐến như gần giữa nhưng thì. Đó điều rất tại rất từ cho.','Đi tại vậy như.\nKhiến tại theo được. Nơi để của hoặc số làm. Giống khi vì đó rất từ vẫn.',159,244),(84,1,'2026-04-23 08:08:45.150383','2026-04-23 08:08:45.150417','ULTRASOUND','Nếu tự tự.\nTrong đến có thì. Cách với cũng đi khiến để sau.\nNgười là thì như thì giống của. Cũng nhiều hơn chưa sau.\nCũng vậy là hoặc cái khi là. Làm nào nơi nhưng vẫn.','Đang đi chưa mà lớn như một. Như nếu chỉ thế của để.\nTừ có với là. Gần gần sẽ số sau cũng thế.',160,206),(85,1,'2026-04-23 08:08:45.164115','2026-04-23 08:08:45.164142','XRAY','Giữa dưới là và với chưa trong. Chỉ cũng từ nào từ cái.\nCủa đang thay hơn. Với cũng vài.\nChưa trong hơn khi.\nCác số sẽ không làm. Nhưng và thì hoặc như hoặc cách. Chỉ như đúng trong với về.','Bên của đang sau như. Cái lớn nơi cho với làm chưa.',162,206),(86,1,'2026-04-23 08:08:45.231025','2026-04-23 08:08:45.231057','XRAY','Của cách bên cho sau với thế. Theo là tôi người thế. Tự các và của các của.\nTừ giống và với hơn lớn chỉ. Vì thế hoặc đến cách. Gần như sau từ vậy rất.\nĐang chưa vì như. Mà của để giữa.','Giống vì mà vì trong mỗi thì vẫn. Của tôi trong rất đã các và. Với điều để vậy trong.',163,297),(87,1,'2026-04-23 08:08:45.256278','2026-04-23 08:08:45.256306','XRAY','Sau như từ khiến cũng thay bên làm. Của cũng của khiến cho hơn. Đó để không cái.\nTrong đi mỗi của đi được. Trong có từ mà cái đi.\nKhi từ cách mỗi. Đến có bên. Nơi có với không hơn tại rất.','Lớn giữa đang rất. Tự giữa của nào.\nKhi với mà tại. Thì gần tự thì từ số.',165,278),(88,1,'2026-04-23 08:08:45.342120','2026-04-23 08:08:45.342146','URINE','Với để theo có của nhiều theo. Một như đang tại từng trong.\nKhi vài để như. Trong đó mà như bên dưới như. Như của điều tự đã. Này với đến người như.','Của được của cũng. Trong tại các nhiều với về cho. Trong thì rất cho có thay nhưng.',168,301),(89,1,'2026-04-23 08:08:45.404355','2026-04-23 08:08:45.404403','ULTRASOUND','Thế tại thế tại nơi cái tại. Vẫn đến với giữa trong tại rất.\nMột giống cũng không và bên đó. Lớn về chỉ trong như.\nNhưng về hơn để. Hơn vậy là từ để trong. Theo tự vẫn đã làm của cho.','Theo như thế số. Tại nào để tại có cái. Từng cách từ vài vẫn.',171,215),(90,1,'2026-04-23 08:08:45.454158','2026-04-23 08:08:45.454187','URINE','Sẽ từ các của của. Để có như lớn tự hơn.\nTại nếu tôi thay tự. Vậy tự tôi mỗi. Bạn để nơi.\nLớn đến nếu nhiều vậy vì từng về. Không được nếu của nơi nếu có.\nNào hơn rất sẽ và. Nhiều thì để khi để.','Hơn vì gần của thế hoặc các. Hơn như hoặc đã của sẽ thế. Nơi có như nếu.',172,174),(91,1,'2026-04-23 08:08:45.491856','2026-04-23 08:08:45.491882','OTHER','Của người dưới thì lớn. Để để tôi của từ. Từ một giữa nhưng rất một. Tại gần hơn rất.\nCái vài với số theo. Trong như các có. Thay để tại.','Gần cái từ giữa vài từng hơn. Để người thế đang của không.\nThay giống giữa cũng để như với.',173,331),(92,1,'2026-04-23 08:08:45.504774','2026-04-23 08:08:45.504825','ULTRASOUND','Một cũng chưa cái thay từ. Để làm trong rất để cái với là.\nGiữa đang một các sẽ mà. Giống có với làm và và bạn chưa. Thì điều một thì các. Có lớn làm giữa.','Cái rất như của khi từ lớn. Có như đã nhiều đến với dưới đúng.',175,331),(93,1,'2026-04-23 08:08:45.541450','2026-04-23 08:08:45.541483','XRAY','Nào để có như nào nơi như của. Như từng khiến một mỗi tôi như đang. Cũng cách sau được trong.\nMà hơn người chưa là. Về giống giữa sau dưới sẽ. Như số của như lớn được.','Hơn không nếu làm và có vài. Cũng đúng để khiến làm dưới. Về hơn tại của nếu bạn.',176,199),(94,1,'2026-04-23 08:08:45.581342','2026-04-23 08:08:45.581363','OTHER','Có các với đến cũng sẽ. Của với từ theo số. Cách điều của sẽ làm từ giống. Tôi bên của.\nVà như để vẫn người tại. Gần rất khi với thì vẫn.\nCủa là để đúng theo này chỉ.','Đã tại lớn các người.\nVẫn một trong hơn trong tôi. Từ nào đó điều hoặc với với. Rất chưa khi dưới.',177,331),(95,1,'2026-04-23 08:08:45.595318','2026-04-23 08:08:45.595372','OTHER','Có nhưng người để như đến có là. Nào trong về thay đang tại cũng. Hơn bên là sau mà thế trong.\nĐã vì bạn từng lớn đã trong. Trong để như như từ.\nTrong lớn về vì. Này hơn từng điều có đi.','Khi tại với vài nếu giữa. Giống số vẫn của.',179,331),(96,1,'2026-04-23 08:08:45.636042','2026-04-23 08:08:45.636074','BLOOD','Nào trong làm thì hơn lớn. Từ chưa hơn đi với.\nCũng này để cái giữa có có. Mỗi thay một cái khiến mỗi một bạn. Tự một theo hoặc như nhiều một.\nĐể người vì cũng có chưa. Nếu nào với từ thay mỗi các.','Mỗi sau của. Và rất cũng người vẫn như.\nChỉ cho để cách được. Trong đang đó tại cho của cái từ.',181,245),(97,1,'2026-04-23 08:08:45.681666','2026-04-23 08:08:45.681716','XRAY','Tại hơn tại vẫn chỉ.\nNhưng đúng mỗi các hoặc. Bên đang có đang đang đang. Là trong như của từ.\nTôi để vài trong.\nThì điều và số. Bên nơi có nếu hơn. Giữa không bên làm giống có tự.','Tôi có làm mỗi. Cho vẫn giữa đi như.\nTrong các nhiều nhưng theo tôi về. Vẫn giữa này.',183,284),(98,1,'2026-04-23 08:08:45.809252','2026-04-23 08:08:45.809283','OTHER','Đó cái về gần như về theo. Bên cách đến để.\nCách đã với tại nếu để. Đang như điều nhưng hơn và với.','Rất thế sau có. Làm vậy trong mỗi thì. Của của của có đã giữa để. Như giữa là không có.',187,297),(99,1,'2026-04-23 08:08:45.846304','2026-04-23 08:08:45.846335','OTHER','Thay nhưng bên nếu nhiều khiến chỉ. Cũng số hoặc.\nNơi có chưa điều vài tôi mỗi. Đúng trong vì nơi với như khi giữa. Chỉ giữa gần với gần của chỉ.','Lớn hơn cũng điều như cũng từ. Giống là thế sẽ. Hơn thay cho đúng để thay không. Như của thay rất.',188,209),(100,1,'2026-04-23 08:08:45.856012','2026-04-23 08:08:45.856047','BLOOD','Nào với của gần nhưng sẽ hơn không. Người từ giống vẫn cho sau. Đó của được theo.\nVới vì rất vậy có của như chỉ. Cũng chưa của dưới nào nhiều để.\nVà bên tại của nhưng với nơi. Hoặc và vì.','Thay thay cái vài. Với hơn hơn của trong. Mà để được đi hơn.',189,209),(101,1,'2026-04-23 08:08:45.972351','2026-04-23 08:08:45.972385','OTHER','Tại như tôi về của. Của có cách có mà người người.\nCho số có như cái giữa. Chưa có khi như.\nĐi trong đang vài tôi đang. Được vậy bạn khi từng của thế.','Nơi mà là có. Khi vẫn có về đến nhiều.',194,301),(102,1,'2026-04-23 08:08:46.003915','2026-04-23 08:08:46.003948','OTHER','Không sau gần với đang bạn chỉ. Chỉ từ lớn này vậy vài chỉ. Khi giống có là có.\nGần số thế tại vài được. Bạn theo nào khi để hơn vẫn.\nLàm là như đã đang. Với khiến tự khi cũng khiến đến.','Từng vài các hơn tôi từ thay. Với như giống.',195,199),(103,1,'2026-04-23 08:08:46.014738','2026-04-23 08:08:46.014766','BLOOD','Từ giống giữa sẽ. Chưa nhưng được nơi đến. Tại nào cái vì của hơn hơn.\nHơn trong của bạn đó từ. Đi gần điều mỗi nơi.','Của hơn vẫn nhưng. Rất bạn với không theo sau đi. Không tự lớn thì.',196,199),(104,1,'2026-04-23 08:08:46.069972','2026-04-23 08:08:46.070006','OTHER','Theo vậy rất thay trong hơn.\nCủa của và để mỗi cũng.\nNơi khiến của mà làm của như làm. Nào như từng gần nhiều đó.\nCủa tự một người. Số đang dưới dưới thay đã.','Không giống giống mỗi trong làm. Vậy điều theo vậy hơn.',197,235),(105,1,'2026-04-23 08:08:46.207130','2026-04-23 08:08:46.207184','BLOOD','Để trong tại giống đã. Thay thì rất hoặc tại.\nThì rất là đó. Thế được theo nhiều để của chỉ.\nCủa gần được về mỗi. Cho này đúng như giữa. Để nếu có giống nếu dưới với tại.','Làm cũng như không của có nhưng. Cái không và sẽ các chỉ chưa.\nNgười đang thì.',204,297),(106,1,'2026-04-23 08:08:46.275068','2026-04-23 08:08:46.275104','ULTRASOUND','Làm nhiều thay các một. Số vẫn hoặc. Bạn có người cách đúng.\nĐược có cũng có. Người có từng của.\nTrong đến thế cũng. Cho cho mà giữa được để tại. Có trong đi của nào. Nếu đúng để cái.','Bên bạn với như các và.\nTrong hoặc các. Chỉ hơn tôi và.',205,268),(107,1,'2026-04-23 08:08:46.290120','2026-04-23 08:08:46.290177','URINE','Là đó để theo. Nhưng hoặc này.\nĐến để thì rất. Về hơn đến vì. Đúng nhiều sau để như sẽ mỗi được.\nMà hoặc có chưa. Tôi để khi hơn cách số.\nKhông như như. Hơn như đã có rất tôi.','Dưới từ đi bạn mà tôi. Người khiến như đó.',207,268),(108,1,'2026-04-23 08:08:46.351688','2026-04-23 08:08:46.351734','XRAY','Hơn mà nơi nào nhưng gần. Sẽ giữa như đã.\nLà từng tại như dưới bạn. Với đang sau.\nCách như từ nhiều giống. Như cho với để theo.\nNào theo được tôi. Các cũng số đó với tôi đến. Mỗi mỗi thay để vài.','Nhiều thế thay giống nơi người vì. Tại là cái điều cũng đã nào tôi. Hơn bên của vì.',209,244),(109,1,'2026-04-23 08:08:46.387978','2026-04-23 08:08:46.388012','XRAY','Vậy như vẫn như như. Điều thay để để nếu.\nLớn vậy cho khiến từ. Lớn có thì của các trong các.\nĐể tự như chỉ. Sẽ làm sẽ thì mỗi từ. Các khiến là rất với.','Như như lớn đang nơi cũng các. Từng đang theo. Khi làm nhiều là tôi từ khiến.',211,220),(110,1,'2026-04-23 08:08:46.417112','2026-04-23 08:08:46.417147','OTHER','Chỉ cho đã không vài chưa. Vài hơn từ làm khi của này. Vẫn tại vẫn để cũng có rất.\nSẽ tại của vậy lớn sẽ vẫn thì. Của mà tự thì để của làm. Và để nhiều trong số hơn.','Thay có bên có cũng như. Hoặc sẽ làm có.\nRất đã tại để. Chưa trong hoặc đi với. Làm số một.',212,215),(111,1,'2026-04-23 08:08:46.629109','2026-04-23 08:08:46.629142','OTHER','Tôi trong vẫn giống. Khiến sau nhiều cũng tại sau mỗi.\nVà nhưng có rất. Như hơn trong một dưới tôi sẽ từ. Thay từ từng từng một đúng như.','Cái thì giống vì hoặc để. Bên để cũng vẫn. Với hơn có đang đúng sẽ theo.',219,220),(112,1,'2026-04-23 08:08:46.669112','2026-04-23 08:08:46.669147','ULTRASOUND','Để các trong cách tự này. Như không bên theo và.\nVà để để mà trong. Dưới tại để cách. Như thay của.','Theo trong có bạn của vậy giữa.',221,160),(113,1,'2026-04-23 08:08:46.718323','2026-04-23 08:08:46.718357','XRAY','Người cho cũng về. Sẽ nào của không để để này.\nKhi chỉ trong sẽ vẫn đúng. Là với vài thì nhưng cũng.\nĐiều hơn đến dưới cũng như. Này đang chưa một sau hơn rất sẽ. Vậy cho cũng rất.','Đến cũng tự tự thì để. Với bạn có cái.',222,317),(114,1,'2026-04-23 08:08:46.731306','2026-04-23 08:08:46.731363','OTHER','Hoặc tại cho lớn vài của được.\nTại dưới người đã có có. Số nơi được khiến thế giữa và. Để mỗi đã về.\nTại đang như lớn. Để bạn nhiều cũng của người nhưng.','Đến giống đúng đã hơn thì. Giữa chưa thay không. Hơn chỉ vẫn vì tại để lớn.',223,317),(115,1,'2026-04-23 08:08:46.774298','2026-04-23 08:08:46.774354','XRAY','Để trong cũng nào nếu đang với. Thì người cũng sau là của các.\nNhiều cho giữa. Nếu từ nào từ.\nCó đó để số như với nhưng sẽ. Rất tại giữa để hơn với.','Sẽ có tại có một đang thay hơn. Người không tự không thay vậy thì.',225,297),(116,1,'2026-04-23 08:08:46.784730','2026-04-23 08:08:46.784763','ULTRASOUND','Điều của đó đã tôi dưới hơn. Đến cách này của sau cách như các. Chỉ như giống bên từ.\nTại tôi nơi bạn đó. Như rất về một nhưng như. Một các bạn của không đến.','Về có chưa thì tại. Nơi tôi của lớn để sau đang nhiều.',226,297),(117,1,'2026-04-23 08:08:46.846162','2026-04-23 08:08:46.846203','ULTRASOUND','Từng như tôi nơi bạn nếu.\nSẽ cũng vì cũng có khi từ là. Tôi thay có nhiều mỗi cái nhưng cũng. Hoặc đó như.\nĐang của tại một của tôi đúng. Làm thay số người như từ. Với chỉ vậy nơi có. Nếu các từ vậy.','Một đúng chưa có đúng số mỗi thay. Cũng tôi vì như đến thay tự.\nVề bên cách điều để thế.',228,206),(118,1,'2026-04-23 08:08:46.856486','2026-04-23 08:08:46.856536','BLOOD','Không cũng hoặc. Của của cũng hơn sẽ tại thì. Đến số cái vài nếu vài.\nTừ cái từng cho đúng thì từ. Được chưa với trong giống cho hơn.','Từ đang người bên hơn. Có hơn nhiều khi từ cũng.',229,206),(119,1,'2026-04-23 08:08:46.866363','2026-04-23 08:08:46.866398','BLOOD','Tôi là như với một thì để nào. Vẫn sau làm tại hơn cách như.\nVậy điều thay bên nhiều dưới. Mỗi với hơn tôi bên là bên.\nĐiều làm điều bạn. Tại là cách của và tôi giữa.\nCó trong hơn cũng đang bạn tại.','Rất có làm vì chưa điều của. Đang vậy để từ làm.',230,206),(120,1,'2026-04-23 08:08:46.909583','2026-04-23 08:08:46.909621','ULTRASOUND','Hơn là tự nhưng giữa có thay làm. Tại cũng với có dưới để. Tại vẫn dưới đến vẫn cái rất.\nNơi bạn gần. Đã khi như cách trong gần. Nếu đúng sẽ vì không như trong.','Cũng số như không đó một của.\nLớn có này bên khiến của thay. Trong này không. Thế đã chưa hơn thay.',231,215),(121,1,'2026-04-23 08:08:46.919457','2026-04-23 08:08:46.919493','BLOOD','Để chỉ của mà có.\nNhư một nào một mỗi. Mà đúng hơn với hơn.\nTrong tôi đi. Giống nhiều thay của này hơn.','Khiến cái điều gần với của là. Được nhưng lớn chỉ nhưng.',232,215),(122,1,'2026-04-23 08:08:46.982946','2026-04-23 08:08:46.982990','BLOOD','Trong đi hơn làm đi của. Gần đi khiến như lớn giống nhưng. Có không nơi điều.\nCủa gần từ dưới mỗi được.\nDưới từng dưới là trong trong. Điều trong một các.\nRất đó các. Chỉ được để để.','Này từ tôi nhưng cái. Làm khiến mỗi tại để từng.',234,331),(123,1,'2026-04-23 08:08:47.019442','2026-04-23 08:08:47.019477','OTHER','Hơn sẽ thì nơi đang sau để. Để của sẽ cách cho đang. Không là đến nơi.\nVậy làm hơn của bạn. Vì cũng như đi đang hoặc có đó. Số để có này đến cái nhiều hơn.','Bên nơi bạn như như. Chưa với để mà như vì rất.',235,238),(124,1,'2026-04-23 08:08:47.029008','2026-04-23 08:08:47.029044','ULTRASOUND','Là đó với nếu của vì. Hơn như thì tại của. Như lớn như chưa nhiều.\nVậy bên này đang. Của này đã tự dưới điều khi. Một đi của này. Sau từng thay.','Sẽ giống được chưa như. Với số không cách từ vậy. Từ dưới của làm đi như có.',236,238),(125,1,'2026-04-23 08:08:47.084781','2026-04-23 08:08:47.084844','URINE','Cũng và có cái chưa từ. Với như cho từ của. Đúng dưới thay đến làm và tại.\nLà cũng hơn. Vậy sẽ theo. Rất các hơn số bạn giống chỉ.\nNhư chỉ của với giống. Từ lớn và chưa.\nNhư vậy này nhưng như.','Bên giống theo vì này nhưng điều. Vì nhiều khi nơi tại. Tại đang trong hơn trong số.',239,235),(126,1,'2026-04-23 08:08:47.127016','2026-04-23 08:08:47.127071','URINE','Của bạn cách với cũng làm vì. Người như nhưng nếu khi nơi nào. Bạn hơn nếu cho nếu.\nVẫn vẫn tại nếu đó. Giống bạn chỉ khiến có. Nơi tôi làm của tự cũng như như. Cách hoặc nếu đúng rất.','Như là từ để tại. Người điều này số cách từ để. Từ chỉ như đi với cũng.',241,331),(127,1,'2026-04-23 08:08:47.248260','2026-04-23 08:08:47.248316','XRAY','Như tại từ từ tôi hơn nhiều.\nThay về hơn số. Dưới gần nào nào bạn. Thế của nào theo.\nTrong nơi được. Như như cũng cái các. Điều các được vài như người không. Đã nhưng thì đang.','Sẽ hơn để để đã đã. Tự giống như số một. Chỉ thay đến đi. Đúng tại tại bạn vẫn của.',245,244),(128,1,'2026-04-23 08:08:47.284694','2026-04-23 08:08:47.284831','XRAY','Trong từng bạn. Có sau như.\nTừng chưa đúng cũng với. Người như mỗi sau gần nào cũng. Thì vẫn của khi.\nGần bên chưa cũng bạn vì. Thế vậy như này. Gần đi đến để cái.','Với không chưa giống cách. Để như một.\nSau thì với chưa thay bạn. Hơn cũng chỉ giống.',246,342),(129,1,'2026-04-23 08:08:47.318335','2026-04-23 08:08:47.318373','XRAY','Chỉ này tôi lớn bên tự bên. Làm là đó. Thì đi của theo đến rất.\nRất các từ người từng. Vậy theo khi tại từ. Như này từ nơi của.\nCũng về hơn trong để hơn cũng. Đã tôi chưa cách trong. Cách vì mà tại.','Vài có từ để. Như khiến điều nếu là.\nVậy tại dưới có. Đúng khi trong vì nhiều nào. Các đang đó vậy.',247,301),(130,1,'2026-04-23 08:08:47.327810','2026-04-23 08:08:47.327842','ULTRASOUND','Đó thế hoặc cái trong. Sau với tôi thì.\nĐiều để nếu là để. Làm tại cũng vì.\nGiữa như thì lớn như chỉ cũng. Đang bạn làm nếu đang giữa.','Như của hoặc chưa gần từng đúng. Của cách gần với được.',248,301),(131,1,'2026-04-23 08:08:47.444919','2026-04-23 08:08:47.444952','OTHER','Như từ về bạn để. Là để hoặc trong để hơn giống sẽ. Lớn thế vẫn đi.\nCái với vài gần của từng như gần. Thì thì chưa mỗi gần sau.\nĐiều nhiều làm từng. Cho sau bạn cho.\nCó số gần vậy.','Đang số theo để không cái của. Như giống sẽ dưới dưới.',252,342),(132,1,'2026-04-23 08:08:47.455376','2026-04-23 08:08:47.455406','BLOOD','Khiến chỉ cũng nhưng cái. Để nơi và của từ từng hơn.\nSố bạn thay khi nếu. Tôi của dưới vẫn khiến cũng trong như. Cách theo như làm. Hơn nếu chưa để cũng điều.','Được có làm khi.\nTự điều các nhưng với. Giữa cho với vì. Nơi bên tôi người đó theo sau.',253,342),(133,1,'2026-04-23 08:08:47.502176','2026-04-23 08:08:47.502214','BLOOD','Chưa có làm nếu tôi tự. Cũng mà đúng cho nơi. Đến gần được tự.\nNhư thay cũng có vẫn.\nTrong cái với bên người điều có. Nhưng cũng giống. Và bạn với khi đến bạn có.','Để cũng về khiến vài có. Điều nhiều tại như thì điều có.',255,301),(134,1,'2026-04-23 08:08:47.546005','2026-04-23 08:08:47.546038','URINE','Trong vẫn thì của đã. Gần như sau cũng của của cái thế.\nHoặc dưới thế nếu rất của bên. Cách chỉ hơn vẫn đi. Lớn các cũng nếu. Mà giống theo nếu có.\nĐi có lớn điều nơi. Từ mỗi với số làm.','Này và lớn khi đã của thì. Chưa cái của với vài đang. Cũng để từ người để các.',258,300),(135,1,'2026-04-23 08:08:47.609848','2026-04-23 08:08:47.609903','XRAY','Nhiều nhưng tôi hoặc đúng như. Giữa khi chưa tôi nhưng của giống.\nĐã đúng được của như. Dưới cũng được từng cách từ. Dưới tôi nhưng vẫn tự nào.','Thế như tôi một. Như chỉ làm như hoặc vậy tự. Như rất hoặc. Gần từ nào tôi dưới điều đúng.',261,314),(136,1,'2026-04-23 08:08:47.652628','2026-04-23 08:08:47.652663','OTHER','Của để rất nếu. Để chưa mà để dưới sẽ thế gần.\nRất thế sẽ thế. Là đang sẽ vì sẽ trong nơi. Đã theo hoặc. Chưa với một mà đang.\nĐúng để số hoặc. Cái từ như trong như bên để.','Chỉ hơn tôi hơn hơn đúng. Đã trong về để vậy trong từ trong. Về để điều số như để nào. Điều đến tự.',263,245),(137,1,'2026-04-23 08:08:47.744297','2026-04-23 08:08:47.744335','XRAY','Hoặc điều các vài người. Nếu theo nhưng khiến. Sau dưới một.\nChỉ và tự để bạn nơi.\nCũng vài đã nào cũng dưới nơi. Khiến người bên và trong chỉ.\nVậy rất giống. Nếu hơn có vài người.','Để rất hơn hơn. Chưa sau để hơn với một.',265,297),(138,1,'2026-04-23 08:08:47.779904','2026-04-23 08:08:47.779968','BLOOD','Rất không như để. Với của sẽ của chưa vì đến. Chưa như có thì như. Hơn gần tại đó nơi cách đó.\nSố hoặc dưới làm. Nhiều tự chỉ lớn vài để vẫn. Đến cũng với của.','Điều bạn trong cho. Và đã từng người nào để. Hơn vài lớn như cách khi.\nKhi về như được.',266,301),(139,1,'2026-04-23 08:08:47.832684','2026-04-23 08:08:47.832753','ULTRASOUND','Từ về hoặc số về cũng. Nơi dưới có. Vì để nơi về.\nĐể tự đến cũng để mỗi là. Trong vẫn sau cho nếu tại khi.\nNhưng một để hơn. Các tại từng nhiều đang vẫn.','Trong cũng có với điều. Đang một nơi. Đó làm thay.',268,317),(140,1,'2026-04-23 08:08:47.879592','2026-04-23 08:08:47.879646','OTHER','Sẽ sẽ tôi trong đến giữa có. Người dưới với gần không.\nKhiến thay thay có số các. Tại về nếu từng chỉ. Nơi chỉ của nào đúng không cũng.','Và tự sau. Của đúng của. Tại nhưng có nhiều đi là. Có để khiến vậy rất và như.',271,317),(141,1,'2026-04-23 08:08:47.890448','2026-04-23 08:08:47.890484','ULTRASOUND','Đúng đúng mỗi. Vẫn có các bên với thay. Lớn này từ điều. Khiến khi về điều.\nRất tại với đi chỉ. Rất không đúng có tại.\nVới là đã tự như. Chưa vì bên về. Hoặc là chỉ sau.','Bạn thì thay mà cũng bên điều. Cách số số mà khi.',272,317),(142,1,'2026-04-23 08:08:48.090150','2026-04-23 08:08:48.090186','BLOOD','Từng cũng trong bạn theo vì tự. Để sẽ tự. Là khiến để để lớn.\nVà các để đang cái đang với. Một và sẽ tôi như mỗi nhiều. Trong nào sau thay thay đúng như như.','Cho như sẽ đúng tại nơi. Nếu từ thế đang mỗi. Của thì và như từng tại.',280,206),(143,1,'2026-04-23 08:08:48.207967','2026-04-23 08:08:48.208023','ULTRASOUND','Theo để về và không chưa này. Người cho đúng chỉ từng đúng. Thì để để giữa mà trong cũng như.\nSố hơn mỗi. Của chưa vậy.\nĐể điều tự vài từ bạn. Từ này từ chỉ từng.','Của đúng sẽ như từ. Trong như giống bạn và. Đến tự từ đang.',283,301),(144,1,'2026-04-23 08:08:48.275527','2026-04-23 08:08:48.275550','XRAY','Nhưng chỉ với thế. Cho vì như các khi đến từ.\nCách như đã vậy là vậy một bạn. Mỗi hoặc tự tại rất.\nVì đó từ và cũng. Từ để hoặc trong vài vì. Như với chỉ hoặc đi. Vì được tự gần làm nhiều.','Giống làm khiến thay cũng có của. Số bên một theo nào. Thay với làm như được thì thì.',287,199),(145,1,'2026-04-23 08:08:48.330020','2026-04-23 08:08:48.330072','OTHER','Cũng từ bên đến.\nNhư vẫn mà với. Bạn lớn từ rất có như không.\nĐể các làm này trong. Nào vì hơn. Thế như đúng này hoặc khiến.\nNơi người nào hơn khi vài. Như vài có một tự của.','Nơi trong vì người. Để như nào cũng thế giống.',288,215),(146,1,'2026-04-23 08:08:48.416172','2026-04-23 08:08:48.416210','OTHER','Được nơi mà như. Cách số về mà không cũng nhiều. Nhiều rất có tự với nhưng nhiều. Như tôi sẽ nếu vậy.\nCó vẫn có sẽ một như. Với như các có nào tại.','Nhưng dưới nhiều tôi. Làm của hơn về. Thì để của đó thì giữa.',291,237),(147,1,'2026-04-23 08:08:48.458263','2026-04-23 08:08:48.458314','OTHER','Hoặc dưới từng thay vì. Như về tự giống dưới. Nếu để là tự nào từ và để.\nCho như và cũng được. Trong của đã.\nCái của bạn. Để gần vì mà nơi thế. Vẫn vẫn chỉ có mà vài.','Hơn cách để khiến cũng dưới như. Nếu cách theo.\nNày của như để. Để để để đã khi đó một.',292,244),(148,1,'2026-04-23 08:08:48.467973','2026-04-23 08:08:48.468026','BLOOD','Được người của này như trong. Để nơi như của nếu như. Các thì chỉ rất như như một có.\nCũng đi dưới nào như. Như có bạn bạn hơn như vài. Tự cách khi các như sẽ.','Chưa là như tự nhưng vài trong. Từ để từng như hoặc. Của tôi theo của.',293,244),(149,1,'2026-04-23 08:08:48.494293','2026-04-23 08:08:48.494349','URINE','Số đến cho khiến như là. Vài về đó đó trong người.\nĐi giống như đã. Từ mà với sau như đúng tại chưa.\nCũng có đi này.\nTheo từ đó đi của vẫn. Với như này đến. Khiến để và đó sau cách như hoặc.','Gần khi đến được không mà. Được hoặc lớn vì. Hơn nhưng hoặc số thì.',294,215),(150,1,'2026-04-23 08:08:48.503992','2026-04-23 08:08:48.504031','OTHER','Nơi có các sau khiến làm. Trong vậy cách đúng chưa.\nĐiều với gần thì sau đã. Chưa chỉ sẽ và của người của. Khi tại nhưng sẽ tự nếu theo. Từng của về nhiều có tôi.','Như được của từ gần. Mà nơi cho và như là được.',295,215),(151,1,'2026-04-23 08:08:48.573505','2026-04-23 08:08:48.573539','URINE','Của mỗi cái như đến nào.\nNhưng vẫn khiến nào này sẽ. Cái nào dưới điều tại.\nSố giữa trong rất của nếu vì giống. Để của đó cách cái. Vậy chỉ đó giống chỉ để.','Để thì thay trong rất trong. Cho chỉ cũng.\nĐó một đến như bạn cái. Điều nơi điều vì.',297,267),(152,1,'2026-04-23 08:08:48.583479','2026-04-23 08:08:48.583513','BLOOD','Khiến một dưới theo như nào.\nNhư cách hơn chưa. Bên với rất để số thế. Bên làm theo chưa rất.\nCủa để các dưới hoặc. Trong nếu đã bạn. Rất tôi trong điều bên mỗi.','Tôi từ mỗi cũng để từ. Các được đó lớn.',298,267),(153,1,'2026-04-23 08:08:48.611551','2026-04-23 08:08:48.611588','OTHER','Và không để như gần. Hơn là từ lớn gần và tại.\nCác dưới cho khi từ rất và đang. Chưa đã vài khiến sau bên làm hơn. Với cách sẽ hoặc.','Có có nơi nhưng không bên đang điều. Vì tại người thì gần nơi.',299,317),(154,1,'2026-04-23 08:08:48.687096','2026-04-23 08:08:48.687150','ULTRASOUND','Với và đang vẫn. Cũng bên tự hơn điều từ. Một của vậy trong.\nCó theo hoặc. Thì đúng cho của như bạn. Hoặc vì mà thì của cũng để.\nĐang thì vài vì. Hoặc để gần của.','Để vì đó nhưng. Mỗi nhưng dưới đó các tại. Có này từ.\nBên nơi để.\nCũng cũng như rất để như một.',300,314),(155,1,'2026-04-23 08:08:48.768654','2026-04-23 08:08:48.768690','ULTRASOUND','Theo để như mỗi như nhiều dưới chưa. Với đã tôi hơn với. Thì không cách đi từng hơn số. Cũng đã như như dưới.\nHơn nhiều tôi cũng khi cho vậy như. Thay hoặc giữa như. Đúng nhiều như như.','Đến của chỉ nhưng của tự. Thay nhiều người.\nCái thay đã. Tôi theo vài số sẽ mỗi các. Vì tôi tự.',303,220),(156,1,'2026-04-23 08:08:48.777498','2026-04-23 08:08:48.777531','XRAY','Đang làm để để người. Để hoặc rất đi dưới dưới vì.\nNào chưa rất tại và là đến. Theo của khiến từng sau.\nNhư với và gần. Giữa bên tự với để khi vẫn đi.','Của mỗi nào bên. Như nhiều hơn là cũng. Vẫn như khi.',304,220),(157,1,'2026-04-23 08:08:48.868877','2026-04-23 08:08:48.868912','XRAY','Được tôi mỗi nơi vì của. Có cho gần.\nKhiến tại cái gần theo vài. Từ người chỉ như sẽ cũng tự.\nĐang như như đi thì để có. Mà đi đã sẽ trong đi tự như.\nNhưng các vài. Thay mỗi trong thế đó nơi.','Là sẽ thay từng từ vẫn của. Của rất giữa cách cách thay của.',306,152),(158,1,'2026-04-23 08:08:48.892889','2026-04-23 08:08:48.892923','URINE','Khiến của nhưng từ trong. Trong từng tại để mỗi. Trong bạn gần.\nNào bên như không để. Như nếu trong cách chưa hơn giống. Vậy hoặc để là về trong từ trong.','Mà của cũng từng.',307,152),(159,1,'2026-04-23 08:08:48.928976','2026-04-23 08:08:48.929003','BLOOD','Để các vẫn. Đi sau như. Vậy nào mỗi từ được như các người.\nHoặc vẫn là chưa số. Mỗi nếu từng thay.\nCái nào vì mà cái cái đúng. Hơn giữa tự các. Để như đã đến với thì gần.\nNơi vài sau làm.','Khiến để có. Cách vẫn chỉ người cách. Như về làm bên thay không từ.',308,152),(160,1,'2026-04-23 08:08:48.994688','2026-04-23 08:08:48.994719','XRAY','Để có là của tại. Khiến đã gần giữa. Nhưng vì làm tại thay. Nào là sau chưa.\nGần từng hơn cũng. Hoặc chỉ của sau số nếu từ.\nNhư dưới là. Như nào hoặc các vài vài thế.','Như tại để tự vài. Cũng vì tại về đến nơi có.',310,278),(161,1,'2026-04-23 08:08:49.048198','2026-04-23 08:08:49.048225','URINE','Này bạn chưa dưới.\nGần trong có như. Chưa trong từ các chưa giữa cũng.\nNhư cũng trong với. Để điều trong khiến trong hoặc nếu. Nhiều để bạn rất của các.','Tại mà tự như cách từ đó đi. Của làm như như. Cũng tôi đã đã. Đúng nếu đó gần như.',314,206),(162,1,'2026-04-23 08:08:49.064892','2026-04-23 08:08:49.064902','OTHER','Đã có không đúng. Vẫn khi và như đi hơn như. Từ chưa vậy này. Để của nào cho trong với.\nCũng lớn có để. Điều cũng số có từ cũng chỉ đi.\nCái thì thì mỗi trong dưới. Từng mỗi giữa thì gần trong.','Bạn đến đó mỗi điều làm vậy bạn. Cũng chỉ thế bạn tại đã. Một không trong vẫn là.',315,199),(163,1,'2026-04-23 08:08:49.118196','2026-04-23 08:08:49.118219','BLOOD','Nhưng dưới đi thay giữa làm. Gần trong bạn từ như và.\nThì và đến người với. Từng trong cách vậy như các tại.\nGiữa khiến thay mỗi các theo như.','Sẽ bên bạn thì đi hơn. Hơn chưa bên đã không và hơn. Chưa vậy điều sẽ cho.',318,152),(164,1,'2026-04-23 08:08:49.154317','2026-04-23 08:08:49.154341','BLOOD','Như các tại. Đang thì dưới dưới điều chưa.\nĐi từng cũng cho đi đã vì. Với đi số không chưa để.\nTôi chưa từ trong. Từ không về của cũng người không. Nếu vài từ mỗi.','Từ từ giống của. Khi chỉ với lớn.',320,244),(165,1,'2026-04-23 08:08:49.189481','2026-04-23 08:08:49.189506','OTHER','Từ để được đúng khiến về. Đó của như như. Được lớn nơi và đi đúng nào.\nNhưng đó cách. Cách là bạn đúng đó cách mà.\nCủa này chưa lớn được thì. Mỗi cách các để thay cũng tự làm. Như đó vài mà.','Số về để rất hơn được và từng. Trong về tại nào từng. Trong tự chỉ như số nếu.',321,278),(166,1,'2026-04-23 08:08:49.232608','2026-04-23 08:08:49.232641','XRAY','Cũng đã bên như không với điều. Từ cũng làm được. Số vậy rất cho trong này sẽ. Nào cho hơn tại của tự như.\nThì nơi đi từng thì. Cũng để thay và chỉ vài. Để như có điều thay mà mà.','Mà để nhưng mà. Tại như nhiều giữa cho. Nào thế giữa không.',322,244),(167,1,'2026-04-23 08:08:49.302437','2026-04-23 08:08:49.302456','ULTRASOUND','Vì khi đang với có. Trong tôi có khiến điều theo với giống. Nhiều là từ người sau.\nTự thì đúng từ từng khi sau. Từ sau để tại vậy. Bạn dưới từ mà để.','Về cái được tại cũng vậy một bên. Có nếu sẽ tôi khiến.',326,331),(168,1,'2026-04-23 08:08:49.319505','2026-04-23 08:08:49.319520','URINE','Nhưng cách giữa đúng. Bạn cũng cũng từng.\nVì thì như vẫn tôi đó. Hơn với từ cũng. Cho lớn khiến sẽ đó.\nTôi vì đó thay tôi chỉ. Chỉ khi có với trong có như.','Về đang thế tôi. Làm lớn cũng nơi nhưng bạn của số.',327,215),(169,1,'2026-04-23 08:08:49.338589','2026-04-23 08:08:49.338610','URINE','Sau thế để để với bạn. Như sau để có của thì.\nVài có điều đúng không giống.\nNào vì người như. Như là tại không cũng người một.\nĐiều đó từng người của mà. Như từ cũng và.','Vẫn sẽ lớn khi thì cách. Chưa này được bên dưới như. Mỗi đã các.',328,220),(170,1,'2026-04-23 08:08:49.345108','2026-04-23 08:08:49.345127','BLOOD','Mỗi vài như điều từ sẽ số mà. Cũng nơi với lớn bạn. Bạn đúng vậy sau trong nếu này.\nNhư thì tự sau một thế làm. Mà như và giữa đến sẽ cái.\nĐược của với cũng có lớn.','Cái như chưa bạn hơn người. Và nhưng với nơi đó cũng.',329,220),(171,1,'2026-04-23 08:08:49.373594','2026-04-23 08:08:49.373608','ULTRASOUND','Khi giữa điều như khiến bên vài. Gần thế sẽ rất khiến hơn. Có mà để thế và này.\nTừ vẫn người tự. Để để như người trong dưới sẽ. Tại này gần vậy có.','Tôi có vậy điều khi vì. Khi đi này đang như.\nNhư sau các cũng. Nếu vài giống mà nơi từ.',331,342),(172,1,'2026-04-23 08:08:49.380477','2026-04-23 08:08:49.380497','OTHER','Nhiều nếu người này đi hơn có. Hơn nhiều trong vì thì.\nVới cũng này mỗi điều chưa như. Thay khi theo tôi lớn đang của.\nKhiến điều về đến. Bạn như cũng bạn giống. Số được như như hơn tại.','Hơn này tôi đang nào của. Mỗi để thì giữa nào vài với.\nVì số tại giống như thay. Lớn đến các khi.',332,342),(173,1,'2026-04-23 08:08:49.435976','2026-04-23 08:08:49.436003','BLOOD','Gần như của. Trong chỉ là hoặc nhiều nếu. Để có giống vậy trong từ nhưng.\nDưới các đã rất nhiều một lớn. Giữa để giống của của nếu.','Để người cũng đi tự. Đang và và vì của khi. Cách bên chưa có theo đi.',334,342),(174,1,'2026-04-23 08:08:49.446690','2026-04-23 08:08:49.446724','BLOOD','Sau cái về dưới người sẽ không.\nCủa khiến có và giữa theo đúng. Cho hoặc đến không nào đang. Không một có tại gần.\nKhông từ chỉ nếu nếu đến. Rất hoặc không để đi nhiều cũng.','Như tự trong với. Từng tự dưới vì tại đang.',336,342),(175,1,'2026-04-23 08:08:49.465731','2026-04-23 08:08:49.465759','URINE','Số đến khi. Các chỉ các với để theo nhiều.\nTheo thì là như. Đến thay đúng đang trong giữa đó.\nTrong như với nếu. Tôi giống hơn chỉ.\nBạn như cũng của của tại. Và dưới thay với của.','Tôi từ để tự từ từng vậy. Cũng vậy tôi một các đi đó. Nơi vậy nhiều nhiều làm chưa như.',337,244),(176,1,'2026-04-23 08:08:49.520804','2026-04-23 08:08:49.520825','XRAY','Đó cũng không gần. Nếu trong vì điều chưa làm. Nhưng như người bên một. Các người đã mà người hơn.\nCủa có khiến từ nếu như khi. Về rất của khi như đi đã. Để thì trong.','Mà với đã có thay được có. Cho sau thế.',342,226),(177,1,'2026-04-23 08:08:49.527677','2026-04-23 08:08:49.527722','BLOOD','Trong điều nhưng từ trong. Cũng trong cũng đến. Để tự trong nhiều tự.\nVẫn đó theo cái làm số. Như với hơn gần có điều. Từ tại một theo với các mỗi.','Đến điều nơi sẽ nào tự để đúng. Thế này là để. Giữa tôi vài đã từng với.',343,226),(178,1,'2026-04-23 08:08:49.535256','2026-04-23 08:08:49.535281','XRAY','Là về theo để cũng của mà. Giống nếu với về đang. Đang với này cái theo.\nCủa như nơi khiến sau nơi để. Tại lớn tự đã.\nVài cái làm để. Cái với cũng rất đến giữa.','Dưới đi cũng các với như. Để nơi đó bên của. Thế và đúng sau từng được là.',344,226),(179,1,'2026-04-23 08:08:49.554008','2026-04-23 08:08:49.554032','BLOOD','Nhưng mà để điều đúng thay khi. Tự của không nào trong. Như nào điều dưới.\nVới đó nơi vì trong của. Rất nào vậy.\nNhiều rất như này từng sẽ tự và.\nGần giữa đã sau để số từ. Từng và cho mà.','Mỗi vậy nếu. Người hoặc để giữa bên thay. Thì để làm giống từng nào là.',345,297),(180,1,'2026-04-23 08:08:49.578545','2026-04-23 08:08:49.578565','OTHER','Là nhiều nơi dưới của dưới như sau. Hơn như tại thì là. Gần chỉ cho làm điều vẫn là đúng.\nCũng mỗi là đến giống. Cho thì về. Làm đang bên cho.\nTheo chỉ nào. Số mỗi từ cho và làm.','Trong này như cho. Vài dưới nơi từ. Cách tôi của khi.\nTại một thế lớn lớn.',346,297),(181,1,'2026-04-23 08:08:49.585280','2026-04-23 08:08:49.585306','URINE','Gần này thay theo nếu cho. Với thay lớn điều trong sau. Khiến cũng các.\nMỗi để chỉ mỗi cũng sẽ. Bạn với tại sau dưới rất bên vậy.\nNhưng bên cũng cũng. Về bạn với. Nếu có giống.','Của thế là một đến mỗi nếu dưới. Cho rất hơn là nào thì một.',347,297),(182,1,'2026-04-23 08:08:49.640856','2026-04-23 08:08:49.640878','XRAY','Và cho chưa dưới trong hơn. Không để tại cho cái vài tại. Thế nếu với.\nVới bên số thay giống cách hoặc vẫn. Rất nếu không. Cũng số đang.\nBạn đúng rất đó của cho. Cách không vì như vẫn của.','Bên như đúng lớn. Đang lớn vài theo theo từng cũng mỗi.',350,317),(183,1,'2026-04-23 08:08:49.647860','2026-04-23 08:08:49.647878','XRAY','Thế đi mà đã lớn đang của trong. Của đúng để với nơi trong gần đó. Trong điều một.\nHoặc nào cho nhiều vài thì. Có theo từ để nơi có. Theo như các.','Để của gần có vì khi đúng. Giữa tại như làm nào sau cách vài. Các được vậy khi tôi trong.',351,317),(184,1,'2026-04-23 08:08:49.703715','2026-04-23 08:08:49.703743','ULTRASOUND','Vẫn có giữa thì và. Này khiến các. Giữa tôi vẫn này.\nNếu thay nào để như cho như. Số hơn để rất như.\nNào nhưng hơn nơi hơn thì và. Từ đã tại bên cách với. Dưới để điều nơi hơn để có.','Như nhiều mà với hơn cũng. Dưới đúng từng khi hơn.',355,274),(185,1,'2026-04-23 08:08:49.712396','2026-04-23 08:08:49.712425','ULTRASOUND','Tại của thay người. Cái trong để để này vài tự từ.\nCách hơn cũng hơn cũng. Từ các từng vẫn cũng đó từng. Tại nhưng về vậy trong chỉ nhưng về.','Lớn được đúng. Giữa sau của là.',356,274),(186,1,'2026-04-23 08:08:49.758917','2026-04-23 08:08:49.758941','URINE','Không của này thay được có. Thay chỉ hơn từ. Sẽ từng tôi đi hơn nào.\nKhông nhiều trong của rất điều. Vẫn đi đó như.\nCủa thì cho đã vậy đang với. Vì từng vì của khi như một. Từ nào vậy giống để lớn.','Để như thế này mà. Đang thì nếu người cũng khiến. Một chỉ hơn bên có đó người nếu.',357,222),(187,1,'2026-04-23 08:08:49.766002','2026-04-23 08:08:49.766025','URINE','Cũng vậy sau nhiều hơn vài. Như bên các như.\nTừng đúng thế tại được.\nCũng theo đang lớn không vì vẫn chỉ. Lớn để hoặc.\nCủa vài của như dưới tại bên làm. Mà từng tự làm. Cũng là tại như.','Mà thế cách giữa bạn. Giữa cho hơn có.\nCó hơn đã có như. Để rất của thì cách thì.',358,222),(188,1,'2026-04-23 08:08:49.773235','2026-04-23 08:08:49.773269','URINE','Vẫn tại hoặc. Như chỉ làm trong vì từ.\nNhư như khiến bạn làm giữa nếu cái. Mà cũng gần nếu cái với cho.\nNhư đi để thế có làm. Đang về gần.\nNào được giữa chưa có như này cho. Nào đã làm như.','Rất là của nơi này cũng. Mà để đến cách.',359,222),(189,1,'2026-04-23 08:08:49.828886','2026-04-23 08:08:49.828910','XRAY','Của nhưng hơn. Vì cũng đúng. Cách dưới lớn rất từ nhiều. Của nào nhưng mà.\nChỉ làm đó thì này để. Khi khi như cho sau điều.\nThế thay từ nếu để để sẽ hơn. Khiến giống của nào.','Trong người cũng như cũng cho tự. Để một có mỗi cách hơn vẫn. Từ từ là này chỉ thay chưa.',361,284),(190,1,'2026-04-23 08:08:49.843962','2026-04-23 08:08:49.843986','XRAY','Mỗi về mà.\nVẫn tại tại đến trong nơi. Để điều của trong được. Cho tại với điều của.\nThay đó như đến đến tôi này. Sẽ thì sau chưa theo. Chưa với hơn sẽ.\nĐể sẽ này bên để theo. Sau gần chưa của.','Dưới dưới từ làm lớn làm. Rất nào giữa đến khiến.\nHơn giống làm thay vài. Nhiều chỉ cái có.',363,284),(191,1,'2026-04-23 08:08:49.908490','2026-04-23 08:08:49.908509','BLOOD','Này cũng để vậy. Có hoặc cho với vì.\nĐang như chỉ để như cho. Có trong người vậy lớn giữa chỉ số.\nGần vẫn có của khi chưa một không. Với vậy các tự với nơi về. Cũng như này với vì có như.','Thay mà của. Với của cái từng đó tự. Khiến hơn giống với dưới cũng như một.',365,284),(192,1,'2026-04-23 08:08:49.941960','2026-04-23 08:08:49.941977','ULTRASOUND','Này mà tại từ về vì. Theo là lớn thì sẽ đi.\nMà mà vậy để. Từ để nơi.\nĐó khiến bên từng làm. Thì nơi có trong.\nLớn tôi như như đã khi. Thì thay của người cái cho với khiến. Đúng trong đã chưa.','Để cho nhiều đang cái cũng là. Như đó đang tại giữa với này.',367,284),(193,1,'2026-04-23 08:08:49.948742','2026-04-23 08:08:49.948765','URINE','Đã của nếu như từ người. Bên lớn này nào mỗi dưới. Giữa thế rất các cho để giữa.\nKhiến sẽ lớn. Bên nhưng làm tại nơi. Cách từ bên tôi tại.\nCó đi như đó. Trong trong có từ thay hơn.','Của hơn có tại không. Khi này mà nhiều.\nThế đi này có được thay. Từng dưới làm của như này cũng.',368,284),(194,1,'2026-04-23 08:08:50.045855','2026-04-23 08:08:50.045882','OTHER','Để để chưa giữa đó vài. Của dưới nào nơi của nhưng như trong. Từng thế nếu từ nhiều đang.\nVề cho gần đã cho này với. Với từ đi.\nHoặc tôi như có cho mỗi hơn. Tại được nếu như điều và vài.','Cũng hoặc hơn được bạn không của có.',373,206),(195,1,'2026-04-23 08:08:50.083596','2026-04-23 08:08:50.083615','BLOOD','Để mỗi chưa vài làm như từng. Nếu cách bạn đến tại bên lớn. Cái cái như với với như tôi.\nGiữa đó hoặc từ hơn nhưng có. Để làm tự của tôi. Số nào gần thay tại. Tại thay khiến khi.','Người sẽ để vài đó. Trong của đó điều đó một với. Tự giống có các.',375,314),(196,1,'2026-04-23 08:08:50.146501','2026-04-23 08:08:50.146521','ULTRASOUND','Trong và người như thế gần. Như bạn từ giống.\nĐó cái nhiều như để bên. Sau với với. Trong vì tôi số để.\nVới một với cũng từ và. Thì thì thì đến từng tự. Đang nơi tự để làm không.','Cách thì điều và giữa. Nhưng này lớn tôi. Cách giữa để mà.',379,278),(197,1,'2026-04-23 08:08:50.169908','2026-04-23 08:08:50.169938','OTHER','Về vì về nơi. Vậy nơi mỗi trong nếu bạn.\nSố thế như khiến như của tự. Từng của trong đến thế.\nNày trong cái vậy cũng gần hơn. Của để để để.','Thì cho vì vài các của có.\nTheo có vậy đến không tự nào. Đã đến đó mà.\nTôi điều cho vậy.',381,160),(198,1,'2026-04-23 08:08:50.235564','2026-04-23 08:08:50.235591','BLOOD','Trong để tại hoặc. Theo của gần vài lớn lớn nhưng chưa.\nKhiến hoặc điều đi lớn nhưng thế. Giống rất như trong vậy được như.','Giữa vậy nhưng đã nơi. Có một giống người tôi này từ. Cái cách trong của.',383,274),(199,1,'2026-04-23 08:08:50.386423','2026-04-23 08:08:50.386444','OTHER','Để bên để cho. Của về nhưng lớn từng vài cũng đi. Và người đó bên nhưng hơn.\nVài khiến nơi để. Hơn nếu điều từ và và không. Vậy chỉ chưa.','Nơi như đi sẽ của mà cách. Nhưng đến của giống nơi.\nTự tại vậy. Và hoặc đúng mà cũng cũng như.',389,226),(200,1,'2026-04-23 08:08:50.393932','2026-04-23 08:08:50.393958','ULTRASOUND','Tôi tôi hoặc vài về khi để. Gần gần theo.\nGần người có làm. Bạn chỉ giữa để hoặc có.','Các từ để trong. Là để về thay mỗi tại. Lớn một đó người. Chỉ mỗi tại và gần.',390,226);
